import React from 'react';
import { Text } from '@chakra-ui/react';

type ZimmProductNameProps = {
  /** The product's display name, already resolved by the caller. */
  name: string;
  /**
   * Heading level. Required rather than defaulted: the correct level depends on what else the
   * page has already emitted, and a silent `h1` default duplicates the base PDP's own
   * screen-reader-only `<h1>Product Details</h1>`.
   */
  as: 'h1' | 'h2' | 'h3';
};

/**
 * Atom — the product name. No recipe: the whole spec is one `textStyle` plus a semantic colour
 * token, which tiers 1-2 of .claude/rules/overrideStyling.md already cover.
 */
export const ZimmProductName = ({ name, as }: ZimmProductNameProps) => (
  <Text as={as} textStyle="heading3" color="text.default" data-testid="product-name">
    {name}
  </Text>
);

