import React from 'react';
import { chakra, useStyleConfig } from '@chakra-ui/react';

type ZimmProductPriceProps = {
  /**
   * The price, already formatted for the storefront's locale and currency by the caller
   * (`intl.formatNumber` at the page). This atom does no formatting of its own so it stays
   * usable from Storybook without an intl provider.
   */
  price: string;
  /** Reserved for SFCC-194's was/now treatment; only `default` is implemented today. */
  variant?: 'default';
};

/**
 * Atom — the single, full product price. Styling lives in `zimmProductPrice.css.ts` and is
 * consumed through the theme, per the one-canonical-styling-surface rule.
 */
export const ZimmProductPrice = ({ price, variant = 'default' }: ZimmProductPriceProps) => {
  const styles = useStyleConfig('ZimmProductPrice', { variant });

  return (
    <chakra.p __css={styles} textStyle="price" data-testid="product-price">
      {price}
    </chakra.p>
  );
};

import type { SystemStyleObject } from '@chakra-ui/react';

/**
 * Recipe for the PDP price.
 *
 * The DS models `pdp/price` with two states, so this carries a `variants` map rather than a
 * bare `baseStyle` — see .claude/rules/overrideStyling.md tier 3. Only `default` is populated:
 * the was/now (sale) treatment belongs to SFCC-194, and its colours and strike-through are not
 * specced anywhere we can read today. Adding a `sale` key that merely echoes `default` would
 * look finished and be wrong, so the extension point is documented instead of stubbed.
 *
 * SFCC-194 adds `sale` alongside `default` below; nothing else in this file needs to change.
 */
export const ZimmProductPrice = {
  baseStyle: {
    margin: 0,
    color: 'var(--zimm-color-text-default)',
  } satisfies SystemStyleObject,

  variants: {
    default: {} satisfies SystemStyleObject,
  },

  defaultProps: {
    variant: 'default',
  },
};

