import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { useUiCopy } from 'app/hooks/useUiCopy';

// English fallback for useUiCopy() below — not a prop. Named so the string appears once, the
// same way zimmSubscribeSection/index.tsx keeps its fallbacks.
const LABEL_FALLBACK = 'Style Code:';

type ZimmProductStyleCodeProps = {
  /**
   * The master product's style number. This is the style code shown to shoppers, which is not
   * the same value as the variant `product.id`.
   */
  value?: string;
};

/**
 * Atom — the "Style Code: 7300JS261" line. Renders nothing when no style code is available.
 *
 * The label is microcopy, so it comes from `useUiCopy()` rather than a prop: it is the same
 * string for every caller, and the hook is Context-backed app-wide static content, which
 * components.md explicitly allows a presentational leaf to read. With no UiCopyProvider
 * mounted (Storybook, a unit test) it degrades to the fallback above, so this stays renderable
 * with zero setup.
 */
export const ZimmProductStyleCode = ({ value }: ZimmProductStyleCodeProps) => {
  const styles = useMultiStyleConfig('ZimmProductStyleCode', {});
  const { t } = useUiCopy();
  if (!value) return null;

  return (
    <chakra.div __css={styles.root} textStyle="caption" data-testid="product-style-code">
      <chakra.span __css={styles.label}>{t('pdp.styleCodeLabel', LABEL_FALLBACK)}</chakra.span>
      {/*
        A real space so `textContent` — what a screen reader reads out and what a shopper
        copies — is "Style Code: 8637DS241", matching both composed page designs. It adds no
        visual width: a whitespace-only anonymous flex item is not rendered (CSS Flexbox §4),
        so the 4px `gap` in the recipe remains the only spacing.
      */}{' '}
      <chakra.span __css={styles.value}>{value}</chakra.span>
    </chakra.div>
  );
};

import type { SystemStyleObject } from '@chakra-ui/react';

/**
 * Recipe for the style-code line. Multipart because the DS models it as two nodes, not one
 * string: label at x=0 (57px wide) and value at x=61 (157px wide) inside the 218px info
 * column. Neither width is reproduced here — they are the measured natural widths of the
 * sample copy, not a spec, and fixing them would break the moment the label is translated
 * (11 locales). The gap between them is the part that carries meaning: 61 - 57 = 4px, which
 * is exactly `spacing['2xs']`.
 *
 * Open with the designer (see the PR body): the DS models this as two nodes while both
 * composed page designs show a single concatenated string, "Style Code: 7300JS261". A flex
 * row of two nodes renders identically to the concatenation, so this satisfies both until the
 * question is settled.
 */
export const ZimmProductStyleCode = {
  parts: ['root', 'label', 'value'],

  baseStyle: (): Record<string, SystemStyleObject> => ({
    root: {
      display: 'flex',
      gap: 'var(--zimm-scale-2xs)',
      color: 'var(--zimm-color-text-default)',
    },
    label: {
      margin: 0,
      whiteSpace: 'nowrap',
    },
    value: {
      margin: 0,
    },
  }),
};

