import React from 'react';
import { Text } from '@chakra-ui/react';
import { isBlankRichText, parseRichText } from 'app/utils/richText';

type ZimmProductModelInfoProps = {
  /**
   * Model copy from the product's `c_modelFit` attribute. Business Manager authors this as
   * rich text, so it is parsed rather than rendered as a raw string.
   */
  modelInfo?: string;
};

/**
 * Atom — the model line ("Model is 178cm and wears a size 0"). Renders nothing when
 * `c_modelFit` is absent, which is the common case today. No recipe: one `textStyle` plus a
 * semantic colour token.
 */
export const ZimmProductModelInfo = ({ modelInfo }: ZimmProductModelInfoProps) => {
  if (isBlankRichText(modelInfo)) return null;
  const content = parseRichText(modelInfo);

  return (
    <Text as="div" textStyle="caption" color="text.default" data-testid="product-model-info">
      {content}
    </Text>
  );
};

