import React, { type ReactNode } from 'react';

/**
 * Renders SFCC-authored rich text (product description, model copy) as React elements.
 *
 * This deliberately does **not** sanitise a string and hand it to `dangerouslySetInnerHTML`.
 * It parses the markup and emits React nodes, so raw HTML is never injected: every text run
 * goes through React's own escaping and every attribute is discarded. The worst case for a
 * malformed or hostile input is that it renders as visible text, not that it executes.
 *
 * Why not `isomorphic-dompurify` — the engine the earlier SFCC-89 attempt on PR #57 adds as a
 * production dependency: importing it anywhere in the SSR graph crashes the server render.
 * webpack bundles jsdom into the server bundle but rewrites `__dirname`, so jsdom's
 * module-scope
 * `fs.readFileSync(path.resolve(__dirname, '../../../browser/default-stylesheet.css'))`
 * resolves outside the project and throws ENOENT at *import* time, before `sanitize()` is ever
 * called. Reproduced on 2026-08-23: a PDP that returns 200 returns 500 with the import present,
 * and the asset is never copied into `build/`, so a production bundle fails the same way. Needs
 * raising with Integration before #57's dependency addition is accepted.
 *
 * Scope: the tag allow-list below covers what Business Manager actually authors today
 * (`<br>`, `<ul>`, `<li>`, plus basic emphasis). Anything outside it is unwrapped — the tag is
 * dropped, its text kept — except for the script-bearing elements, whose content is dropped
 * too so their source does not surface as visible copy.
 */

/** Container and inline elements that are reproduced as real React elements. */
const ALLOWED_TAGS = new Set(['p', 'ul', 'ol', 'li', 'strong', 'em', 'b', 'i']);

/** Allow-listed elements that never have children. */
const VOID_TAGS = new Set(['br']);

/**
 * Elements whose *content* is discarded along with the tag. Unwrapping these would turn
 * script or style source into visible page copy. `iframe`/`object`/`embed` carry no text worth
 * keeping either.
 */
const DROP_CONTENT_TAGS = new Set(['script', 'style', 'template', 'noscript', 'iframe', 'object', 'embed', 'svg']);

/**
 * The HTML void elements. These never have a closing tag, so one must not be treated as
 * opening a region — `<embed src="y">z` would otherwise swallow `z` and everything after it.
 */
const VOID_ELEMENTS = new Set([
  'area',
  'base',
  'br',
  'col',
  'embed',
  'hr',
  'img',
  'input',
  'link',
  'meta',
  'param',
  'source',
  'track',
  'wbr',
]);

/** Elements that hold no text and must not leave a stray text node behind. */
const LIST_CONTAINERS = new Set(['ul', 'ol']);

/**
 * Matches one tag. The alternation in the attribute group lets a quoted attribute value
 * contain `>` (`<a title="a > b">`) without ending the match early.
 */
const TAG_RE = /<(\/?)([a-zA-Z][a-zA-Z0-9-]*)((?:[^>"']|"[^"]*"|'[^']*')*)>/g;

const NAMED_ENTITIES: Record<string, string> = {
  amp: '&',
  lt: '<',
  gt: '>',
  quot: '"',
  apos: "'",
  nbsp: '\u00a0',
  hellip: '…',
  mdash: '—',
  ndash: '–',
  rsquo: '’',
  lsquo: '‘',
  rdquo: '”',
  ldquo: '“',
  deg: '°',
};

const ENTITY_RE = /&(#[Xx][0-9A-Fa-f]+|#\d+|[A-Za-z][A-Za-z0-9]*);/g;

/**
 * Decodes character references in a text run. Applied only to text, never to markup, so an
 * authored `&lt;script&gt;` becomes the literal characters `<script>` and is rendered as text
 * by React rather than re-entering the parser.
 */
export const decodeEntities = (text: string): string =>
  text.replace(ENTITY_RE, (match, entity: string) => {
    if (entity.startsWith('#')) {
      const isHex = entity[1] === 'x' || entity[1] === 'X';
      const codePoint = Number.parseInt(isHex ? entity.slice(2) : entity.slice(1), isHex ? 16 : 10);
      // Reject non-characters and anything past the Unicode range rather than throwing.
      if (!Number.isFinite(codePoint) || codePoint <= 0 || codePoint > 0x10ffff) return match;
      return String.fromCodePoint(codePoint);
    }
    return NAMED_ENTITIES[entity.toLowerCase()] ?? match;
  });

type Frame = { tag: string | null; children: ReactNode[] };

/**
 * Converts an SFCC rich-text string into React nodes.
 *
 * @param html - Raw markup from the Commerce API. `undefined`, `null` and blank input all
 *   return an empty array, so a caller can render `null` when there is nothing to show.
 * @returns The parsed nodes, safe to render directly as children.
 */
export const parseRichText = (html?: string | null): ReactNode[] => {
  if (!html) return [];

  const root: Frame = { tag: null, children: [] };
  const stack: Frame[] = [root];
  const top = () => stack[stack.length - 1];

  // Depth counter for a DROP_CONTENT_TAGS region, so nested same-name tags close correctly.
  let dropTag: string | null = null;
  let dropDepth = 0;

  const pushText = (raw: string) => {
    if (!raw) return;
    // A list container may only hold <li>; whitespace between items would be an invalid text
    // child. Text that is not whitespace is kept, so nothing authored is silently lost.
    const parentTag = top().tag;
    if (parentTag && LIST_CONTAINERS.has(parentTag) && !raw.trim()) return;
    top().children.push(decodeEntities(raw));
  };

  let cursor = 0;
  let match: RegExpExecArray | null;
  TAG_RE.lastIndex = 0;

  while ((match = TAG_RE.exec(html)) !== null) {
    const [full, closing, rawName, attrs] = match;
    const tag = rawName.toLowerCase();

    if (dropDepth === 0) pushText(html.slice(cursor, match.index));
    cursor = match.index + full.length;

    if (dropDepth > 0) {
      if (tag === dropTag) dropDepth += closing ? -1 : 1;
      if (dropDepth === 0) dropTag = null;
      continue;
    }

    if (DROP_CONTENT_TAGS.has(tag)) {
      // A void element (`<embed>`) and a self-closing `<svg/>` both open and close in one
      // token, so neither starts a region to skip.
      if (!closing && !VOID_ELEMENTS.has(tag) && !attrs.trimEnd().endsWith('/')) {
        dropTag = tag;
        dropDepth = 1;
      }
      continue;
    }

    if (closing) {
      if (!ALLOWED_TAGS.has(tag)) continue;
      // Unwind to the matching frame. A stray `</li>` with no open `<li>` leaves the stack
      // untouched rather than closing something it did not open.
      const depth = stack.findIndex((frame) => frame.tag === tag);
      if (depth <= 0) continue;
      while (stack.length > depth) closeTop();
      continue;
    }

    if (VOID_TAGS.has(tag)) {
      top().children.push(React.createElement(tag, { key: `${tag}-${top().children.length}` }));
      continue;
    }

    if (!ALLOWED_TAGS.has(tag)) continue; // unwrap: drop the tag, keep whatever it contains
    if (attrs.trimEnd().endsWith('/')) continue; // self-closed container has no content
    stack.push({ tag, children: [] });
  }

  if (dropDepth === 0) pushText(html.slice(cursor));

  // Unclosed tags still render, with whatever content they collected.
  while (stack.length > 1) closeTop();

  return root.children;

  function closeTop() {
    const frame = stack.pop();
    /* c8 ignore next -- guarded by the `stack.length > 1` conditions at every call site */
    if (!frame?.tag) return;
    const parent = top();
    parent.children.push(
      React.createElement(
        frame.tag,
        { key: `${frame.tag}-${parent.children.length}` },
        frame.children.length ? frame.children : undefined,
      ),
    );
  }
};

/**
 * The visible text of a rich-text value, with all markup removed.
 *
 * Derived by walking the output of `parseRichText` rather than re-stripping the string, so the
 * two can never disagree about what counts as content — a second implementation of the
 * drop/unwrap rules would drift the first time one of them changed.
 *
 * Callers use this to decide whether there is anything to render at all: Business Manager can
 * save a field as `<p></p>` or a bare `<br>`, which parses to real nodes but shows nothing, and
 * rendering it would leave an empty box still contributing to the layout rhythm.
 */
export const richTextToPlainText = (html?: string | null): string => nodeText(parseRichText(html));

const nodeText = (node: ReactNode): string => {
  if (node === null || node === undefined || typeof node === 'boolean') return '';
  if (typeof node === 'string' || typeof node === 'number') return String(node);
  if (Array.isArray(node)) return node.map(nodeText).join('');
  if (React.isValidElement(node)) return nodeText((node.props as { children?: ReactNode }).children);
  /* c8 ignore next -- ReactNode also admits portals and iterables, which this parser never emits */
  return '';
};

/** True when a rich-text value would render nothing visible. */
export const isBlankRichText = (html?: string | null): boolean => richTextToPlainText(html).trim() === '';

