/**
 * G1 — ties the external data shape to the rendered props.
 *
 * Every assertion below uses a value unique to its own field, so a mapping that reads the
 * wrong key fails rather than coincidentally matching. That is the whole point: the failure
 * mode this guards is a field quietly resolving to `undefined` and its line disappearing.
 */
import { describe, expect, test, vi } from 'vitest';
import { selectPdpProductInfo, type PdpSourceProduct } from './productInfo';

/** Distinct sentinel per field — no two share a value. */
const FULL: PdpSourceProduct = {
  id: 'VARIANT-SKU-0001',
  name: 'Natura Mini Dress',
  longDescription: '<p>A long sleeve linen mini dress.</p>',
  master: { masterId: 'MASTER-STYLE-8637' },
  c_modelFit: 'Model is 178cm and wears a size 0',
};

const formatPrice = (amount: number, currency: string) => `${currency} ${amount.toFixed(2)}`;
const map = (
  product: PdpSourceProduct | null | undefined,
  price: { currentPrice?: number } | null = { currentPrice: 895 },
) => selectPdpProductInfo(product, price, 'AUD', formatPrice);

describe('selectPdpProductInfo — every field reaches the right prop', () => {
  test.each`
    prop             | source                      | expected
    ${'name'}        | ${'name'}                   | ${'Natura Mini Dress'}
    ${'description'} | ${'longDescription'}        | ${'<p>A long sleeve linen mini dress.</p>'}
    ${'modelInfo'}   | ${'c_modelFit'}             | ${'Model is 178cm and wears a size 0'}
    ${'styleCode'}   | ${'master.masterId'}        | ${'MASTER-STYLE-8637'}
    ${'price'}       | ${'priceData.currentPrice'} | ${'AUD 895.00'}
  `('$prop <- $source', ({ prop, expected }) => {
    expect(map(FULL)?.[prop as keyof ReturnType<typeof map> & string]).toBe(expected);
  });

  test('styleCode is the master style number, not the variant id', () => {
    // The regression this pins: after the first swatch click `product.id` becomes the variant
    // SKU while the style code shown to shoppers must not change.
    expect(map(FULL)?.styleCode).toBe('MASTER-STYLE-8637');
    expect(map(FULL)?.styleCode).not.toBe(FULL.id);
  });

  test('falls back to product.id for a standard product with no master', () => {
    expect(map({ ...FULL, master: undefined })?.styleCode).toBe('VARIANT-SKU-0001');
  });
});

describe('selectPdpProductInfo — absent fields', () => {
  test.each(['longDescription', 'c_modelFit', 'master'] as const)(
    'a missing %s yields undefined, not a blank string',
    (field) => {
      const info = map({ ...FULL, [field]: undefined });
      expect(info).not.toBeNull();
      // `undefined` matters: the atoms branch on it to render nothing at all. An empty string
      // would still be truthy at some call sites and could render an empty styled node.
      const byField = { longDescription: 'description', c_modelFit: 'modelInfo', master: 'styleCode' } as const;
      if (field !== 'master') expect(info?.[byField[field]]).toBeUndefined();
    },
  );

  test('only name is load-bearing — no name means nothing to render yet', () => {
    expect(map(undefined)).toBeNull();
    expect(map(null)).toBeNull();
    expect(map({ ...FULL, name: undefined })).toBeNull();
    expect(map({ ...FULL, name: '' })).toBeNull();
  });

  test('an absent price renders empty rather than "NaN" or "undefined"', () => {
    expect(map(FULL, null)?.price).toBe('');
    expect(map(FULL, {})?.price).toBe('');
    expect(map(FULL, { currentPrice: undefined })?.price).toBe('');
  });

  test('a genuine zero price is formatted, not treated as absent', () => {
    expect(map(FULL, { currentPrice: 0 })?.price).toBe('AUD 0.00');
  });
});

describe('selectPdpProductInfo — formatting is delegated', () => {
  test('calls the injected formatter once with the storefront currency', () => {
    const spy = vi.fn(() => '$895.00');
    selectPdpProductInfo(FULL, { currentPrice: 895 }, 'AUD', spy);
    expect(spy).toHaveBeenCalledOnce();
    expect(spy).toHaveBeenCalledWith(895, 'AUD');
  });

  test('does no formatting of its own', () => {
    // Guards against a future edit reintroducing a hardcoded symbol or locale here; currency
    // presentation differs across the 8 storefronts and belongs to react-intl.
    expect(selectPdpProductInfo(FULL, { currentPrice: 895 }, 'HKD', (a, c) => `${c}${a}`)?.price).toBe('HKD895');
  });
});

