/**
 * `parseRichText` is the seam between Business-Manager-authored copy and the DOM, so its
 * rejection behaviour is the thing worth pinning down. Every hostile-input case below is a
 * row in one table, asserted against the *rendered* markup rather than the node tree — that
 * is the form an attacker would have to reach, and it is what a reviewer can read at a glance.
 *
 * `renderToStaticMarkup` is deliberate: it proves the output as React actually serialises it,
 * including React's own text escaping, rather than re-implementing that escaping in the test.
 */
import { describe, expect, test } from 'vitest';
import React from 'react';
import { renderToStaticMarkup } from 'react-dom/server';
import { decodeEntities, isBlankRichText, parseRichText, richTextToPlainText } from './richText';

const render = (input?: string | null) => renderToStaticMarkup(<>{parseRichText(input)}</>);

describe('parseRichText — rejection matrix', () => {
  // Each row: what an attacker or a bad CMS paste could put in the field, and what must
  // survive. `mustNotContain` is checked against the serialised markup.
  test.each`
    name                           | input                                                  | mustNotContain    | mustContain
    ${'script element'}            | ${'<p>hi</p><script>alert(1)</script>'}                | ${'<script'}      | ${'<p>hi</p>'}
    ${'script body is not text'}   | ${'<script>stealCookies()</script>'}                   | ${'stealCookies'} | ${''}
    ${'uppercase SCRIPT'}          | ${'<SCRIPT>alert(1)</SCRIPT>ok'}                       | ${'alert(1)'}     | ${'ok'}
    ${'nested script'}             | ${'<script><script>alert(1)</script></script>safe'}    | ${'alert'}        | ${'safe'}
    ${'inline event handler'}      | ${'<p onclick="evil()">text</p>'}                      | ${'onclick'}      | ${'<p>text</p>'}
    ${'img onerror'}               | ${'<img src=x onerror=alert(1)>caption'}               | ${'onerror'}      | ${'caption'}
    ${'javascript: href'}          | ${'<a href="javascript:alert(1)">link</a>'}            | ${'javascript:'}  | ${'link'}
    ${'data: href'}                | ${'<a href="data:text/html,<script>x</script>">l</a>'} | ${'data:'}        | ${'l'}
    ${'iframe'}                    | ${'<iframe src="https://evil.test"></iframe>after'}    | ${'<iframe'}      | ${'after'}
    ${'svg onload'}                | ${'<svg onload=alert(1)></svg>tail'}                   | ${'onload'}       | ${'tail'}
    ${'style block'}               | ${'<style>body{display:none}</style>copy'}             | ${'display:none'} | ${'copy'}
    ${'form and input'}            | ${'<form><input value="x"></form>body'}                | ${'<input'}       | ${'body'}
    ${'object embed'}              | ${'<object data="x"></object><embed src="y">z'}        | ${'<object'}      | ${'z'}
    ${'class attribute stripped'}  | ${'<p class="leak">t</p>'}                             | ${'class'}        | ${'<p>t</p>'}
    ${'style attribute stripped'}  | ${'<p style="position:fixed">t</p>'}                   | ${'style'}        | ${'<p>t</p>'}
    ${'id attribute stripped'}     | ${'<li id="x">t</li>'}                                 | ${'id='}          | ${'<li>t</li>'}
    ${'encoded script stays text'} | ${'&lt;script&gt;alert(1)&lt;/script&gt;'}             | ${'<script'}      | ${'&lt;script&gt;'}
    ${'attr value containing gt'}  | ${'<a title="a > b">shown</a>'}                        | ${'title'}        | ${'shown'}
    ${'unknown tag is unwrapped'}  | ${'<div><span>kept</span></div>'}                      | ${'<div'}         | ${'kept'}
    ${'comment-ish input'}         | ${'<!-- <script>x</script> -->visible'}                | ${'<script'}      | ${'visible'}
  `('$name', ({ input, mustNotContain, mustContain }) => {
    const markup = render(input as string);
    if (mustNotContain) expect(markup).not.toContain(mustNotContain as string);
    if (mustContain) expect(markup).toContain(mustContain as string);
  });

  test('no rejection case ever emits an executable element', () => {
    // Guards the table above against a silently-empty run (a suite that collects nothing
    // passes vacuously). If a row is deleted this count drops and the test fails.
    const hostile = [
      '<script>a</script>',
      '<iframe></iframe>',
      '<img src=x onerror=y>',
      '<svg onload=y></svg>',
      '<object></object>',
      '<embed>',
      '<style>a{}</style>',
      '<form><input></form>',
    ];
    expect(hostile).toHaveLength(8);
    for (const input of hostile) {
      const markup = render(input);
      expect(markup).not.toMatch(/<(script|iframe|img|svg|object|embed|style|form|input)\b/i);
      expect(markup).not.toMatch(/\son[a-z]+=/i);
    }
  });
});

describe('parseRichText — real SFCC copy', () => {
  // The actual shape returned by the Shopper Products API for 8637DS241 (AU, 2026-08-23).
  const REAL = [
    'The Natura Mini Dress in Blue Birds from our Spring 2024 Collection, Natura. ',
    'A long sleeve linen mini dress featuring a deep v-neckline with fitted bodice and full skirt. ',
    '<br><ul><li> Linen mini dress</li><li> Long sleeves with fluted cuffs </li>',
    '<li> Crinoline hem </li><li> Invisible zip at centre back</li></ul>',
  ].join('');

  test('preserves the tags Business Manager actually authors', () => {
    const markup = render(REAL);
    expect(markup).toContain('<br/>');
    expect(markup).toContain('<ul>');
    expect(markup).toContain('<li> Linen mini dress</li>');
    expect(markup).toContain('Invisible zip at centre back');
  });

  test('emits no stray text node inside a list container', () => {
    // `<ul>` may only hold `<li>`; whitespace between items must not become a text child.
    expect(render('<ul>\n  <li>a</li>\n  <li>b</li>\n</ul>')).toBe('<ul><li>a</li><li>b</li></ul>');
  });

  test('keeps non-whitespace text that is not inside a list', () => {
    expect(render('lead in<ul><li>a</li></ul>tail')).toBe('lead in<ul><li>a</li></ul>tail');
  });
});

describe('parseRichText — malformed input', () => {
  test.each([
    ['unclosed tag', '<p>text', '<p>text</p>'],
    ['stray close tag', 'text</p>', 'text'],
    ['mismatched nesting', '<strong><em>x</strong></em>', '<strong><em>x</em></strong>'],
    ['self-closed container', '<p/>after', 'after'],
    ['bare angle bracket', 'a < b and c > d', 'a &lt; b and c &gt; d'],
  ])('%s', (_name, input, expected) => {
    expect(render(input)).toBe(expected);
  });

  test.each([undefined, null, ''])('renders nothing for %s', (input) => {
    expect(parseRichText(input)).toEqual([]);
    expect(render(input)).toBe('');
  });
});

describe('decodeEntities', () => {
  test.each([
    ['&amp;', '&'],
    ['&lt;&gt;', '<>'],
    ['&quot;q&quot;', '"q"'],
    ['&#39;', "'"],
    ['&#x27;', "'"],
    ['&nbsp;', ' '],
    ['&rsquo;', '’'],
    ['5&deg; &mdash; 6&deg;', '5° — 6°'],
  ])('decodes %s', (input, expected) => {
    expect(decodeEntities(input)).toBe(expected);
  });

  test.each(['&notarealentity;', '&#0;', '&#x110000;', '&', '&;'])('leaves %s untouched', (input) => {
    expect(decodeEntities(input)).toBe(input);
  });
});

describe('richTextToPlainText / isBlankRichText', () => {
  test.each([
    ['<p>Hello <strong>there</strong></p>', 'Hello there'],
    ['<ul><li>a</li><li>b</li></ul>', 'ab'],
    ['plain', 'plain'],
    ['<p>a</p><script>dropped()</script>', 'a'],
    ['&amp; entities decoded', '& entities decoded'],
  ])('%s -> %s', (input, expected) => {
    expect(richTextToPlainText(input)).toBe(expected);
  });

  test.each([undefined, null, '', '   ', '<p></p>', '<p>  </p>', '<br>', '<ul></ul>', '<script>x()</script>'])(
    'treats %s as blank',
    (input) => {
      expect(isBlankRichText(input)).toBe(true);
    },
  );

  test.each(['<p>a</p>', 'a', '<ul><li>a</li></ul>', '&nbsp;x'])('treats %s as non-blank', (input) => {
    expect(isBlankRichText(input)).toBe(false);
  });
});

