/**
 * Scoped to this atom's own contract per testing.md: does it render the parsed content, and
 * does it collapse when there is nothing visible to show.
 *
 * `parseRichText`/`isBlankRichText` are mocked. Their behaviour — the whole allow-list and
 * rejection matrix — is exhaustively proven in app/utils/richText.test.tsx, and re-asserting it
 * here would be the duplicate coverage testing.md warns against. What is *not* proven anywhere
 * else is that this component asks the right question before rendering.
 */
import React from 'react';
import { describe, test, expect, vi, beforeEach } from 'vitest';
import { render, screen } from '@testing-library/react';

const parseRichText = vi.fn();
const isBlankRichText = vi.fn();
vi.mock('app/utils/richText', () => ({
  parseRichText: (html?: string | null) => parseRichText(html),
  isBlankRichText: (html?: string | null) => isBlankRichText(html),
}));

import { ZimmProductDescription } from './index';

beforeEach(() => {
  vi.clearAllMocks();
});

describe('ZimmProductDescription', () => {
  test('renders the parsed nodes when there is visible content', () => {
    isBlankRichText.mockReturnValue(false);
    parseRichText.mockReturnValue([<p key="p">A long sleeve linen mini dress.</p>]);

    render(<ZimmProductDescription description="<p>A long sleeve linen mini dress.</p>" />);

    expect(screen.getByTestId('product-description')).toBeInTheDocument();
    expect(screen.getByText('A long sleeve linen mini dress.')).toBeInTheDocument();
  });

  test('collapses when the value parses to nothing visible', () => {
    // e.g. `<p></p>` — real nodes, no text. Rendering it would leave an empty box that still
    // takes a gap in ZimmProductContent's flex column.
    isBlankRichText.mockReturnValue(true);
    parseRichText.mockReturnValue([<p key="p" />]);

    render(<ZimmProductDescription description="<p></p>" />);

    expect(screen.queryByTestId('product-description')).not.toBeInTheDocument();
  });

  test('asks isBlankRichText before parsing, and passes the raw value through unchanged', () => {
    isBlankRichText.mockReturnValue(false);
    parseRichText.mockReturnValue(['x']);
    const raw = '<p>raw &amp; unmodified</p>';

    render(<ZimmProductDescription description={raw} />);

    // Sanitising or trimming here would silently diverge from what the util was tested against.
    expect(isBlankRichText).toHaveBeenCalledWith(raw);
    expect(parseRichText).toHaveBeenCalledWith(raw);
  });

  test('renders nothing when no description is supplied at all', () => {
    isBlankRichText.mockReturnValue(true);
    parseRichText.mockReturnValue([]);

    render(<ZimmProductDescription />);

    expect(screen.queryByTestId('product-description')).not.toBeInTheDocument();
  });
});

