/**
 * Scoped to this atom's own contract per testing.md: given a value or no value, does it render
 * the right branch, and does the label reach the DOM as microcopy rather than a prop.
 *
 * The recipe's own resolution is covered by theme/components/recipeGuards.test.ts and
 * ui-kits/recipeParts.test.ts; the visual result is covered by index.stories.tsx. Neither of
 * those proves the absent-value branch is discoverable from this folder, which is what this is.
 */
import React from 'react';
import { describe, test, expect, vi } from 'vitest';
import { render, screen } from '@testing-library/react';
import { ZimmProductStyleCode } from './index';

describe('ZimmProductStyleCode', () => {
  test('renders the label and value as one readable line', () => {
    render(<ZimmProductStyleCode value="8637DS241" />);
    // The DS models label and value as two nodes; a screen reader and a copy-paste must still
    // see the single string both composed page designs show.
    expect(screen.getByTestId('product-style-code').textContent).toBe('Style Code: 8637DS241');
  });

  test.each([undefined, ''])('renders nothing for %s', (value) => {
    render(<ZimmProductStyleCode value={value} />);
    // The page places this unconditionally, so an absent style code must collapse rather than
    // leave an empty styled node contributing to the stack's rhythm.
    expect(screen.queryByTestId('product-style-code')).not.toBeInTheDocument();
  });

  test('takes the label from useUiCopy, not a hardcoded string', async () => {
    // Proves the copy is actually looked up: a CMS override must win over the fallback. If the
    // label were inlined this passes vacuously, so the assertion is on the overridden value.
    vi.doMock('app/hooks/useUiCopy', () => ({
      useUiCopy: () => ({ t: (_key: string) => 'Código de estilo:', isLoading: false }),
    }));
    vi.resetModules();
    const { ZimmProductStyleCode: Localised } = await import('./index');

    render(<Localised value="8637DS241" />);
    expect(screen.getByTestId('product-style-code').textContent).toBe('Código de estilo: 8637DS241');
    vi.doUnmock('app/hooks/useUiCopy');
  });
});

