import type { Meta, StoryObj } from '@storybook/react-webpack5';
import React from 'react';
import { expect, within } from 'storybook/test';
import { Box } from '@chakra-ui/react';
import { ZimmProductName } from '.';

const meta: Meta<typeof ZimmProductName> = {
  title: 'Commerce/ZimmProductName',
  component: ZimmProductName,
  argTypes: {
    name: { control: 'text' },
    as: { control: 'inline-radio', options: ['h1', 'h2', 'h3'] },
  },
};
export default meta;

type Story = StoryObj<typeof ZimmProductName>;

export const Default: Story = {
  args: { name: 'Natura Mini Dress', as: 'h1' },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    // `as` is a required prop precisely so the heading level is a caller decision; this pins
    // down that it reaches the DOM rather than being swallowed by Chakra's `as` handling.
    await expect(canvas.getByRole('heading', { level: 1, name: 'Natura Mini Dress' })).toBeInTheDocument();
  },
};

export const LongName: Story = {
  name: 'Long name — wraps within the 218px info column',
  // The DS caps the name at 180px inside the 218px column; this shows the wrap behaviour at
  // the real column width rather than at Storybook's default canvas width.
  args: { name: 'Natura Long Sleeve Linen Mini Dress in Blue Birds', as: 'h2' },
  decorators: [
    (Story: React.ComponentType) => (
      <Box width="218px" outline="1px dashed" outlineColor="border.default" padding="xs">
        <Story />
      </Box>
    ),
  ],
};

export const HeadingLevels: Story = {
  name: 'Heading levels',
  render: () => (
    <Box display="flex" flexDirection="column" gap="s">
      <ZimmProductName name="As h1" as="h1" />
      <ZimmProductName name="As h2" as="h2" />
      <ZimmProductName name="As h3" as="h3" />
    </Box>
  ),
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    for (const level of [1, 2, 3] as const) {
      await expect(canvas.getByRole('heading', { level, name: `As h${level}` })).toBeInTheDocument();
    }
  },
};

