import type { Meta, StoryObj } from '@storybook/react-webpack5';
import React from 'react';
import { expect, within } from 'storybook/test';
import { Box } from '@chakra-ui/react';
import { ZimmProductDescription } from '.';

/** The real Shopper Products payload for 8637DS241 (ZimmermannAU, 2026-08-23). */
const REAL_DESCRIPTION = [
  'The Natura Mini Dress in Blue Birds from our Spring 2024 Collection, Natura. ',
  'A long sleeve linen mini dress featuring a deep v-neckline with fitted bodice and full skirt.',
  '<br><ul><li> Linen mini dress</li><li> Long sleeves with fluted cuffs </li>',
  '<li> Crinoline hem </li><li> Invisible zip at centre back</li></ul>',
].join('');

const meta: Meta<typeof ZimmProductDescription> = {
  title: 'Commerce/ZimmProductDescription',
  component: ZimmProductDescription,
  argTypes: {
    description: { control: 'text' },
  },
  decorators: [
    (Story: React.ComponentType) => (
      <Box width="218px">
        <Story />
      </Box>
    ),
  ],
};
export default meta;

type Story = StoryObj<typeof ZimmProductDescription>;

export const Default: Story = {
  args: { description: REAL_DESCRIPTION },
  play: async ({ canvasElement }) => {
    const root = within(canvasElement).getByTestId('product-description');
    const list = root.querySelector('ul');

    // The recipe's block rhythm is easy to lose to a more specific reset — an element-named
    // selector out-specifies `& > * + *` and the margin silently never applies. Nothing else
    // would catch that: the copy still renders, just flush against the paragraph above it.
    await expect(list).not.toBeNull();
    await expect(getComputedStyle(list as Element).marginBlockStart).toBe('20px');

    // Chakra's global reset strips list markers; the recipe restates that deliberately, so a
    // change to the global registry cannot silently reintroduce bullets here.
    await expect(getComputedStyle(list as Element).listStyleType).toBe('none');
  },
};

export const Absent: Story = {
  name: 'Absent — renders nothing',
  args: { description: undefined },
  play: async ({ canvasElement }) => {
    // The page places this unconditionally, so "no description" must collapse rather than
    // leave an empty styled box that still contributes margin to the stack.
    await expect(within(canvasElement).queryByTestId('product-description')).not.toBeInTheDocument();
  },
};

export const HostileInput: Story = {
  name: 'Hostile input — nothing executable reaches the DOM',
  args: {
    description: [
      '<p onclick="evil()">Legitimate copy.</p>',
      '<script>alert(1)</script>',
      '<img src=x onerror=alert(1)>',
      '<iframe src="https://evil.test"></iframe>',
      '<a href="javascript:alert(1)">a link</a>',
    ].join(''),
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const root = canvas.getByTestId('product-description');

    // The unit test in app/utils/richText.test.tsx asserts the serialised string; this asserts
    // the live DOM, which is the form that would actually execute.
    await expect(root.querySelector('script, iframe, img, object, embed, a')).toBeNull();
    for (const el of Array.from(root.querySelectorAll('*'))) {
      await expect(Array.from(el.attributes).filter((a) => a.name.startsWith('on'))).toHaveLength(0);
    }
    // The legitimate copy still survives the stripping.
    await expect(canvas.getByText('Legitimate copy.')).toBeInTheDocument();
    await expect(canvas.getByText('a link')).toBeInTheDocument();
  },
};

