14	 * the TypeScript annotations below, house formatting, and the temporary override
15	 * marker log, which is removed once the override is confirmed to be rendering.
16	 */
17	
18	import React, { Fragment, useCallback, useEffect, useState } from 'react';
19	import { Helmet } from 'react-helmet';
20	import { FormattedMessage, useIntl } from 'react-intl';
21	import { getUpdateBundleChildArray } from '@salesforce/retail-react-app/app/utils/product-utils';
22	
23	// Components
24	import { Box, Button, Stack, Heading, VStack, Skeleton } from '@salesforce/retail-react-app/app/components/shared/ui';
25	import {
26	  useProduct,
27	  useProducts,
28	  useCategory,
29	  useShopperCustomersMutation,
30	  useShopperBasketsV2Mutation as useShopperBasketsMutation,
31	  useCustomerId,
32	  useShopperBasketsV2MutationHelper as useShopperBasketsMutationHelper,
33	} from '@salesforce/commerce-sdk-react';
34	
35	// Hooks
36	import { useCurrentBasket } from '@salesforce/retail-react-app/app/hooks/use-current-basket';
37	import { useVariant } from '@salesforce/retail-react-app/app/hooks';
38	import useNavigation from '@salesforce/retail-react-app/app/hooks/use-navigation';
39	import useEinstein from '@salesforce/retail-react-app/app/hooks/use-einstein';
40	import useDataCloud from '@salesforce/retail-react-app/app/hooks/use-datacloud';
41	import useActiveData from '@salesforce/retail-react-app/app/hooks/use-active-data';
42	import { useServerContext } from '@salesforce/pwa-kit-react-sdk/ssr/universal/hooks';
43	import usePickupShipment from '@salesforce/retail-react-app/app/hooks/use-pickup-shipment';
44	import { useSelectedStore } from '@salesforce/retail-react-app/app/hooks/use-selected-store';
45	import { useMultiship } from '@salesforce/retail-react-app/app/hooks/use-multiship';
46	import { STORE_LOCATOR_IS_ENABLED } from '@salesforce/retail-react-app/app/constants';
47	import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
48	// Project Components
49	import RecommendedProducts from '@salesforce/retail-react-app/app/components/recommended-products';
50	/*
51	 * Relative, not `@salesforce/retail-react-app/app/components/product-view`. The overrides
52	 * resolver (pwa-kit-dev's OverridesResolverPlugin) deliberately skips any request whose
53	 * issuer already lives in `overrides/` — see its `isFromExtends` guard — so a base-path
54	 * import from this file resolves to the *base* component even in the real app build, not
55	 * just in Storybook/Vitest. Base callers (cart, wishlist, bonus-product) still reach our
56	 * override, because their issuer is inside node_modules and so is redirected normally.
57	 */
58	import ProductView from '../../components/product-view';
59	import type {
60	  ChildProductOrderability,
61	  ProductViewHeaderProps,
62	  ProductViewRefScope,
63	} from '../../components/product-view';
64	import Breadcrumb from '@salesforce/retail-react-app/app/components/breadcrumb';
65	import PromoCallout from '@salesforce/retail-react-app/app/components/product-tile/promo-callout';
66	
67	// SFCC-89 — static product information.
68	import { ZimmProductContent } from '../../components/ui-kits/molecules/zimmProductContent';
69	import { ZimmProductModelInfo } from '../../components/ui-kits/atoms/zimmProductModelInfo';
70	import { ZimmProductStyleCode } from '../../components/ui-kits/atoms/zimmProductStyleCode';
71	import { selectPdpProductInfo } from './productInfo';
72	import InformationAccordion from '@salesforce/retail-react-app/app/pages/product-detail/partials/information-accordion';
73	import Island from '@salesforce/retail-react-app/app/components/island';
74	
75	import { HTTPNotFound, HTTPError } from '@salesforce/pwa-kit-react-sdk/ssr/universal/errors';
76	import logger from '@salesforce/retail-react-app/app/utils/logger-instance';
77	
78	// constant
79	import {
80	  API_ERROR_MESSAGE,
81	  EINSTEIN_RECOMMENDERS,
82	  MAX_CACHE_AGE,
83	  TOAST_ACTION_VIEW_WISHLIST,
84	  TOAST_MESSAGE_ADDED_TO_WISHLIST,
85	  TOAST_MESSAGE_ALREADY_IN_WISHLIST,
86	  STALE_WHILE_REVALIDATE,
87	} from '@salesforce/retail-react-app/app/constants';
88	import { rebuildPathWithParams } from '@salesforce/retail-react-app/app/utils/url';
89	import { useHistory, useLocation, useParams } from 'react-router-dom';
90	import { useToast } from '@salesforce/retail-react-app/app/hooks/use-toast';
91	import { useWishList } from '@salesforce/retail-react-app/app/hooks/use-wish-list';
92	import { useStoreLocatorModal } from '@salesforce/retail-react-app/app/hooks/use-store-locator';
93	import { isPickupMethod } from '@salesforce/retail-react-app/app/utils/shipment-utils';
94	import { useProductInventory } from '@salesforce/retail-react-app/app/hooks/use-product-inventory';
95	
96	/*
97	 * `@salesforce/retail-react-app` ships no TypeScript types (see
98	 * overrides/app/types/vendor.d.ts, which falls back to an untyped catch-all for its
99	 * subpaths), so the product / variant / category values this page threads between base
100	 * hooks and base components have no compile-time shape. The aliases below name that gap
101	 * once, in one place, instead of spreading bare `any` through the file — narrow them as
102	 * the real shapes are confirmed.
103	 */
104	type SfccProduct = any;
105	type SfccVariant = any;
106	type SfccCategory = any;
107	
108	/*
109	 * `@salesforce/commerce-sdk-react` types its query/mutation `parameters` more narrowly than
110	 * the base JS page satisfies (it types several always-present values as optional, and takes
111	 * `ids` as an array where the base joins them itself). The casts marked "SDK param widening"
112	 * below exist only to reconcile that; each passes exactly the value the base file passes, so
113	 * none of them changes runtime behaviour.
114	 */
115	
116	/** A basket line item as this page assembles it before handing it to the baskets API. */
117	type BasketLineItem = {
118	  productId?: string;
119	  id?: string;
120	  price?: number;
121	  quantity?: number;
122	  inventoryId?: string;
123	  shipmentId?: string;
124	  bundledProductItems?: Array<{ productId?: string; quantity?: number }>;
125	};
126	
127	/** A child product selection within a product set or bundle. */
128	type ChildProductSelection = {
129	  product?: SfccProduct;
130	  variant?: SfccVariant;
131	  quantity?: number;
132	};
133	
134	/** The imperative handle ProductView exposes for set/bundle child validation. */
135	type ChildProductRef = {
136	  ref: HTMLDivElement | null;
137	  validateOrderability: ProductViewRefScope['validateOrderability'];
138	};
139	
140	/** One row of the array the base ProductView passes to `addToCart`. */
141	type ProductSelectionValue = {
142	  product?: SfccProduct;
143	  variant?: SfccVariant;
144	  quantity?: number;
145	};
146	
147	/**
148	 * Errors thrown by the commerce SDK carry the originating `Response`, which the base
149	 * page reads to map an API status onto an SSR-visible HTTP error.
150	 */
151	type CommerceApiError = Error & { response?: { status?: number } };
152	
153	const ProductDetail = () => {
154	  // react-intl returns an already-bound `formatMessage`, and this destructuring is the base
155	  // file's own shape — the rule cannot see either.
156	  // eslint-disable-next-line @typescript-eslint/unbound-method
157	  const { formatMessage, formatNumber } = useIntl();
158	  const history = useHistory();
159	  const location = useLocation();
160	  const einstein = useEinstein();
161	  const dataCloud = useDataCloud();
162	  const activeData = useActiveData();
163	  const toast = useToast();
164	  const navigate = useNavigation();
165	  const customerId = useCustomerId();
166	  const { onOpen: onOpenStoreLocator } = useStoreLocatorModal();
167	  const multishipEnabled = getConfig()?.app?.multishipEnabled ?? true;
168	  const storeLocatorEnabled = getConfig()?.app?.storeLocatorEnabled ?? STORE_LOCATOR_IS_ENABLED;
169	
170	  /****************************** Basket *********************************/
171	  const { data: basket, isLoading: isBasketLoading } = useCurrentBasket();
172	  const { addItemToNewOrExistingBasket } = useShopperBasketsMutationHelper();
173	  const updateItemsInBasketMutation = useShopperBasketsMutation('updateItemsInBasket');
174	  const { res } = useServerContext();
175	  if (res) {
176	    res.set('Cache-Control', `s-maxage=${MAX_CACHE_AGE}, stale-while-revalidate=${STALE_WHILE_REVALIDATE}`);
177	  }
178	
179	  /*************************** Pick up in Store ********************/
180	  const { selectedStore } = useSelectedStore();
181	  const selectedInventoryId = selectedStore?.inventoryId || null;
182	
183	  const { addInventoryIdsToPickupItems, updateDefaultShipmentIfNeeded, hasPickupItems } = usePickupShipment(basket);
184	
185	  /*************************** Multiship ********************/
186	  const { getShipmentIdForItems } = useMultiship(basket);
187	
188	  /*************************** Product Detail and Category ********************/
189	  const { productId } = useParams<{ productId?: string }>();
190	  const urlParams = new URLSearchParams(location.search);
191	  // SDK param widening: this component only mounts on `/product/:productId`, so one of the
192	  // two is always present. `useParams` types every segment optional by design — see the
193	  // comment on the react-router-dom shim in overrides/app/types/vendor.d.ts.
194	  const requestedProductId = (urlParams.get('pid') || productId) as string;
195	  const {
196	    data: productResponse,
197	    isLoading: isProductLoading,
198	    isError: isProductError,
199	    error: productError,
200	  } = useProduct(
201	    {
202	      parameters: {
203	        id: requestedProductId,
204	        perPricebook: true,
205	        expand: [
206	          'availability',
207	          'promotions',
208	          'options',
209	          'images',
210	          'prices',
211	          'variations',
212	          'set_products',
213	          'bundled_products',
214	          'page_meta_tags',
215	        ],
216	        allImages: true,
217	        ...(selectedInventoryId ? { inventoryIds: selectedInventoryId } : {}),
218	      },
219	    },
220	    {
221	      // When shoppers select a different variant (and the app fetches the new data),
222	      // the old data is still rendered (and not the skeletons).
223	      keepPreviousData: true,
224	    },
225	  );
226	
227	  // Note: Since category needs id from product detail, it can't be server side rendered atm
228	  // until we can do dependent query on server
229	  const {
230	    data: category,
231	    isError: isCategoryError,
232	    error: categoryError,
233	  } = useCategory({
234	    parameters: {
235	      // SDK param widening — `useCategory` is a no-op until the product resolves, exactly as
236	      // in the base file.
237	      id: productResponse?.primaryCategoryId as string,
238	      levels: 1,
239	    },
240	  });
241	
242	  /****************************** Sets and Bundles *********************************/
243	  const [childProductSelection, setChildProductSelection] = useState<Record<string, ChildProductSelection>>({});
244	  const [childProductOrderability, setChildProductOrderability] = useState<Record<string, ChildProductOrderability>>(
245	    {},
246	  );
247	  const [selectedBundleQuantity, setSelectedBundleQuantity] = useState(1);
248	  const childProductRefs = React.useRef<Record<string, ChildProductRef>>({});
249	  // Deviation from the base file: `?.` on `type`. The base reads `productResponse?.type.set`,
250	  // which throws if the API ever returns a product without `type` (the SDK types it optional).
251	  // The two only differ in that already-broken case.
252	  const isProductASet = productResponse?.type?.set;
253	  const isProductABundle = productResponse?.type?.bundle;
254	
255	  const childVariantIds =
256	    isProductABundle || isProductASet
257	      ? Object.keys(childProductSelection)?.map(
258	          (key) => childProductSelection[key].variant?.productId || childProductSelection[key].product?.id,
259	        )
260	      : [];
261	
262	  const { data: variantProductData } = useProducts(
263	    {
264	      parameters: {
265	        // SDK param widening — the base file joins the ids itself and the SDK forwards the
266	        // value verbatim into the query string.
267	        ids: childVariantIds.join(',') as unknown as string[],
268	        allImages: false,
269	        ...(selectedInventoryId ? { inventoryIds: selectedInventoryId } : {}),
270	        expand: ['availability', 'variations'],
271	        select: '(data.(id,inventory,inventories,master))',
272	      },
273	    },
274	    {
275	      enabled: childVariantIds.length > 0,
276	      keepPreviousData: true,
277	    },
278	  );
279	
280	  const product: SfccProduct = useProductInventory(
281	    productResponse,
282	    variantProductData,
283	    selectedInventoryId,
284	    isProductASet,
285	    isProductABundle,
286	  );
287	
288	  /**************** Error Handling ****************/
289	
290	  if (isProductError) {
291	    const errorStatus = (productError as CommerceApiError | null)?.response?.status;
292	    switch (errorStatus) {
293	      case 404:
294	        throw new HTTPNotFound('Product Not Found.');
295	      default:
296	        throw new HTTPError(errorStatus, `HTTP Error ${errorStatus} occurred.`);
297	    }
298	  }
299	  if (isCategoryError) {
300	    const errorStatus = (categoryError as CommerceApiError | null)?.response?.status;
301	    switch (errorStatus) {
302	      case 404:
303	        throw new HTTPNotFound('Category Not Found.');
304	      default:
305	        throw new HTTPError(errorStatus, `HTTP Error ${errorStatus} occurred.`);
306	    }
307	  }
308	
309	  const [primaryCategory, setPrimaryCategory] = useState<SfccCategory>(category);
310	  const variant = useVariant(product);
311	  // This page uses the `primaryCategoryId` to retrieve the category data. This attribute
312	  // is only available on `master` products. Since a variation will be loaded once all the
313	  // attributes are selected (to get the correct inventory values), the category information
314	  // is overridden. This will allow us to keep the initial category around until a different
315	  // master product is loaded.
316	  useEffect(() => {
317	    if (category) {
318	      setPrimaryCategory(category);
319	    }
320	  }, [category]);
321	
322	  /**************** Product Variant ****************/
323	  useEffect(() => {
324	    if (!variant) {
325	      return;
326	    }
327	    // update the variation attributes parameter on
328	    // the url accordingly as the variant changes
329	    const updatedUrl = rebuildPathWithParams(`${location.pathname}${location.search}`, {
330	      pid: variant?.productId,
331	    });
332	    history.replace(updatedUrl);
333	  }, [variant]);
334	
335	  /**************** Wishlist ****************/
336	  const { data: wishlist, isLoading: isWishlistLoading } = useWishList();
337	  const createCustomerProductListItem = useShopperCustomersMutation('createCustomerProductListItem');
338	
339	  const handleAddToWishlist = (product: SfccProduct, variant: SfccVariant, quantity: number) => {
340	    const isItemInWishlist = wishlist?.customerProductListItems?.find(
341	      (i: { productId?: string }) => i.productId === variant?.productId || i.productId === product?.id,
342	    );
343	
344	    if (!isItemInWishlist) {
345	      createCustomerProductListItem.mutate(
346	        {
347	          parameters: {
348	            listId: wishlist.id,
349	            // SDK param widening — `useCustomerId` returns `string | null`; this branch is
350	            // only reachable once a wishlist has loaded, which requires a customer.
351	            customerId: customerId as string,
352	          },
353	          body: {
354	            // NOTE: API does not respect quantity, it always adds 1
355	            quantity,
356	            productId: variant?.productId || product?.id,
357	            public: false,
358	            priority: 1,
359	            type: 'product',
360	          },
361	        },
362	        {
363	          onSuccess: () => {
364	            toast({
365	              title: formatMessage(TOAST_MESSAGE_ADDED_TO_WISHLIST, { quantity: 1 }),
366	              status: 'success',
367	              action: (
368	                // it would be better if we could use <Button as={Link}>
369	                // but unfortunately the Link component is not compatible
370	                // with Chakra Toast, since the ToastManager is rendered via portal
371	                // and the toast doesn't have access to intl provider, which is a
372	                // requirement of the Link component.
373	                <Button variant="link" onClick={() => navigate('/account/wishlist')}>
374	                  {formatMessage(TOAST_ACTION_VIEW_WISHLIST)}
375	                </Button>
376	              ),
377	            });
378	          },
379	          onError: () => {
380	            showError();
381	          },
382	        },
383	      );
384	    } else {
385	      toast({
386	        title: formatMessage(TOAST_MESSAGE_ALREADY_IN_WISHLIST),
387	        status: 'info',
388	        action: (
389	          <Button variant="link" onClick={() => navigate('/account/wishlist')}>
390	            {formatMessage(TOAST_ACTION_VIEW_WISHLIST)}
391	          </Button>
392	        ),
393	      });
394	    }
395	  };
396	
397	  /**************** Add To Cart ****************/
398	  const showToast = useToast();
399	  const showError = (errorMessage?: unknown) => {
400	    const errorText = typeof errorMessage === 'string' ? errorMessage : formatMessage(API_ERROR_MESSAGE);
401	
402	    showToast({
403	      title: errorText,
404	      status: 'error',
405	    });
406	  };
407	
408	  const [pickupInStoreMap, setPickupInStoreMap] = useState<Record<string, boolean>>({});
409	
410	  const handlePickupInStoreChange = (productId: string, checked: boolean) => {
411	    setPickupInStoreMap((prev) => ({
412	      ...prev,
413	      [productId]: checked,
414	    }));
415	  };
416	
417	  const handleAddToCart = async (productSelectionValues: ProductSelectionValue[] = []) => {
418	    try {
419	      let productItems: BasketLineItem[] = productSelectionValues.map((item) => {
420	        const { variant, quantity } = item;
421	        // Use variant if present, otherwise use the main product
422	        const prod = variant || item.product || product;
423	        return {
424	          productId: prod?.productId || prod?.id, // productId for variant, id for product
425	          price: prod?.price,
426	          quantity,
427	        };
428	      });
429	      // Add inventory IDs for pickup items using the hook helper
430	      productItems = addInventoryIdsToPickupItems(productItems, pickupInStoreMap, selectedStore);
431	      // Defensive check: This block ensures that if, for any reason, pickup is selected for a product but no store (inventoryId) is set,
432	      // we show an error. With the current UI logic, this should never be reached, but it guards against unexpected state.
433	      if (
434	        productItems.some(
435	          (item) => item.inventoryId === undefined && pickupInStoreMap[(item.productId || item.id) as string],
436	        )
437	      ) {
438	        showError(
439	          formatMessage({
440	            id: 'product_view.error.no_store_selected_for_pickup',
441	            defaultMessage: 'No valid store or inventory found for pickup',
442	          }),
443	        );
444	        return;
445	      }
446	
447	      // Check if any products have pickup selected
448	      const hasAnyPickupSelected = hasPickupItems(productSelectionValues, pickupInStoreMap, product);
449	
450	      const currentShippingMethodIsPickup = isPickupMethod(basket?.shipments?.[0]?.shippingMethod);
451	      // Only perform the check if the basket exists and has at least one item
452	      if (!multishipEnabled && basket && basket.productItems?.length > 0) {
453	        if (hasAnyPickupSelected && !currentShippingMethodIsPickup) {
454	          throw new Error(
455	            formatMessage({
456	              id: 'product_view.error.select_ship_to_address',
457	              defaultMessage: "Select 'Ship to Address' to match the delivery method for the items in your cart.",
458	            }),
459	          );
460	        }
461	        if (!hasAnyPickupSelected && currentShippingMethodIsPickup) {
462	          throw new Error(
463	            formatMessage({
464	              id: 'product_view.error.select_pickup_in_store',
465	              defaultMessage: "Select 'Pick Up in Store' to match the delivery method for the items in your cart.",
466	            }),
467	          );
468	        }
469	      }
470	
471	      // Fetch and assign a suitable shipment for product items
472	      const targetShipmentId = await getShipmentIdForItems(hasAnyPickupSelected, selectedStore);
473	
474	      if (targetShipmentId) {
475	        productItems = productItems.map((item) => ({
476	          ...item,
477	          shipmentId: targetShipmentId,
478	        }));
479	      }
480	
481	      const basketResponse = await addItemToNewOrExistingBasket(productItems);
482	
483	      // Configure shipping method for default shipment based on pickup selection
484	      await updateDefaultShipmentIfNeeded(basketResponse, targetShipmentId, hasAnyPickupSelected, selectedStore);
485	
486	      const productItemsForEinstein = productSelectionValues.map(({ product, variant, quantity }) => ({
487	        product,
488	        productId: variant?.productId || product?.id,
489	        price: variant?.price || product?.price,
490	        quantity,
491	      }));
492	      einstein.sendAddToCart(productItemsForEinstein);
493	
494	      return productSelectionValues;
495	    } catch (error) {
496	      showError((error as Error).message);
497	    }
498	  };
499	
500	  /**************** Product Set/Bundles Handlers ****************/
501	  const handleChildProductValidation = useCallback(() => {
502	    // Run validation for all child products. This will ensure the error
503	    // messages are shown.
504	    Object.values(childProductRefs.current).forEach(({ validateOrderability }) => {
505	      validateOrderability({ scrollErrorIntoView: false });
506	    });
507	
508	    // Using ot state for which child products are selected, scroll to the first
509	    // one that isn't selected and requires a variant selection.
510	    const selectedProductIds = Object.keys(childProductSelection);
511	    const firstUnselectedProduct = product?.childProducts?.find(
512	      ({ product: childProduct }: { product: SfccProduct }) => {
513	        // Skip validation for standard products (no variations)
514	        if (childProduct.type?.item) {
515	          return false;
516	        }
517	        return !selectedProductIds.includes(childProduct.id);
518	      },
519	    )?.product;
520	
521	    if (firstUnselectedProduct) {
522	      // Get the reference to the product view and scroll to it.
523	      const { ref } = childProductRefs.current[firstUnselectedProduct.id];
524	
525	      if (ref?.scrollIntoView) {
526	        ref.scrollIntoView({
527	          behavior: 'smooth',
528	          block: 'end',
529	        });
530	      }
531	
532	      return false;
533	    }
534	
535	    return true;
536	  }, [product, childProductSelection]);
537	
538	  /**************** Product Set Handlers ****************/
539	  // 1. Gather the selected child products from state.
540	  // 2. Call handleAddToCart with the selected products.
541	  // 3. The add-to-cart modal will be opened in handleAddToCart.
542	  const handleProductSetAddToCart = () => {
543	    // Get all the selected products, and pass them to the addToCart handler which
544	    // accepts an array.
545	    const productSelectionValues = Object.values(childProductSelection);
546	    return handleAddToCart(productSelectionValues);
547	  };
548	
549	  /**************** Product Bundle Handlers ****************/
550	  // Top level bundle does not have variants
551	  const handleProductBundleAddToCart = async ([{ quantity: selectedQuantity }]: Array<{ quantity?: number }>) => {
552	    try {
553	      const childProductSelections = Object.values(childProductSelection);
554	      // Check if any products have pickup selected (including main product and bundle items)
555	      const bundleSelectionValues = [{ product, variant: null, selectedQuantity }, ...childProductSelections];
556	      const hasAnyPickupSelected = hasPickupItems(bundleSelectionValues, pickupInStoreMap, product);
557	
558	      // Check for delivery method conflicts before adding to cart
559	      if (!multishipEnabled && basket && basket.productItems?.length > 0) {
560	        const currentShippingMethod = basket?.shipments?.[0]?.shippingMethod;
561	        const currentShippingMethodIsPickup = isPickupMethod(currentShippingMethod);
562	
563	        // If there's no shipping method, treat it as non-pickup (ship to address)
564	        if (hasAnyPickupSelected && (!currentShippingMethod || !currentShippingMethodIsPickup)) {
565	          throw new Error(
566	            formatMessage({
567	              id: 'product_view.error.select_ship_to_address',
568	              defaultMessage: "Select 'Ship to Address' to match the delivery method for the items in your cart.",
569	            }),
570	          );
571	        } else if (!hasAnyPickupSelected && currentShippingMethod && currentShippingMethodIsPickup) {
572	          throw new Error(
573	            formatMessage({
574	              id: 'product_view.error.select_pickup_in_store',
575	              defaultMessage: "Select 'Pick Up in Store' to match the delivery method for the items in your cart.",
576	            }),
577	          );
578	        }
579	      }
580	
581	      let productItems: BasketLineItem[] = [
582	        {
583	          productId: product.id,
584	          price: product.price,
585	          quantity: selectedQuantity,
586	          // The add item endpoint in the shopper baskets API does not respect variant selections
587	          // for bundle children, so we have to make a follow up call to update the basket
588	          // with the chosen variant selections
589	          bundledProductItems: childProductSelections.map((child) => {
590	            return {
591	              productId: child.variant?.productId || child.product?.id,
592	              quantity: child.quantity,
593	            };
594	          }),
595	        },
596	      ];
597	
598	      // Add inventory IDs for pickup items using the hook helper
599	      productItems = addInventoryIdsToPickupItems(productItems, pickupInStoreMap, selectedStore);
600	
601	      // Fetch and assign a suitable shipment for product items
602	      const targetShipmentId = await getShipmentIdForItems(hasAnyPickupSelected, selectedStore);
603	
604	      if (targetShipmentId) {
605	        productItems = productItems.map((item) => ({
606	          ...item,
607	          shipmentId: targetShipmentId,
608	        }));
609	      }
610	
611	      const res = await addItemToNewOrExistingBasket(productItems);
612	
613	      const bundleChildMasterIds = childProductSelections.map((child) => {
614	        return child.product.id;
615	      });
616	
617	      // since the returned data includes all products in basket
618	      // here we compare list of productIds in bundleProductItems of each productItem to filter out the
619	      // current bundle that was last added into cart
620	      // Deviation from the base file: `?.` on `productItems`. The SDK types it optional; the
621	      // base file assumes the just-created basket always has line items.
622	      const currentBundle = res.productItems?.find((productItem: SfccProduct) => {
623	        if (!productItem.bundledProductItems?.length) return;
624	        const bundleChildIds = productItem.bundledProductItems?.map((item: { productId?: string }) => {
625	          // seek out the bundle child that still uses masterId as product id
626	          return item.productId;
627	        });
628	        return bundleChildIds.every((id: string) => bundleChildMasterIds.includes(id));
629	      });
630	
631	      const itemsToBeUpdated = getUpdateBundleChildArray(currentBundle, childProductSelections);
632	
633	      if (itemsToBeUpdated.length) {
634	        // make a follow up call to update child variant selection for product bundle
635	        // since add item endpoint doesn't currently consider product bundle child variants
636	        await updateItemsInBasketMutation.mutateAsync({
637	          // SDK param widening — `method` is a real, honoured option on the v2 baskets
638	          // mutation (the base file relies on it to send PATCH rather than the default), but
639	          // it is absent from the published mutation-parameter type. Dropping it would change
640	          // the HTTP verb, so the argument is asserted instead.
641	          method: 'PATCH',
642	          parameters: {
643	            // `res` is the basket this call just wrote to.
644	            basketId: res.basketId as string,
645	          },
646	          body: itemsToBeUpdated,
647	        } as Parameters<typeof updateItemsInBasketMutation.mutateAsync>[0]);
648	      }
649	
650	      // Configure shipping method based on pickup selection
651	      await updateDefaultShipmentIfNeeded(res, targetShipmentId, hasAnyPickupSelected, selectedStore);
652	
653	      einstein.sendAddToCart(productItems);
654	
655	      return childProductSelections;
656	    } catch (error) {
657	      showError(error);
658	    }
659	  };
660	
661	  /**************** Einstein ****************/
662	  useEffect(() => {
663	    if (product && product.type.set) {
664	      einstein.sendViewProduct(product);
665	      dataCloud.sendViewProduct(product);
666	      const childrenProducts = product.setProducts;
667	      childrenProducts.map((child: SfccProduct) => {
668	        try {
669	          einstein.sendViewProduct(child);
670	        } catch (err) {
671	          logger.error('Einstein sendViewProduct error', {
672	            namespace: 'ProductDetail.useEffect',
673	            additionalProperties: { error: err, child },
674	          });
675	        }
676	        activeData.sendViewProduct(category, child, 'detail');
677	        dataCloud.sendViewProduct(child);
678	      });
679	    } else if (product) {
680	      try {
681	        einstein.sendViewProduct(product);
682	      } catch (err) {
683	        logger.error('Einstein sendViewProduct error', {
684	          namespace: 'ProductDetail.useEffect',
685	          additionalProperties: { error: err, product },
686	        });
687	      }
688	      activeData.sendViewProduct(category, product, 'detail');
689	      dataCloud.sendViewProduct(product);
690	    }
691	  }, [product]);
692	
693	  /**************** SFCC-89 — static product information ****************/
694	  const formatPrice = (amount: number, priceCurrency: string) =>
695	    formatNumber(amount, { style: 'currency', currency: priceCurrency });
696	
697	  /**
698	   * Replaces the title/price block of ProductView's header with the Zimmermann content group.
699	   *
700	   * The breadcrumb and promo callout are reproduced from the base header rather than dropped:
701	   * `renderHeader` replaces the whole header block, and neither of those belongs to SFCC-89
702	   * (breadcrumb is SFCC-578, badges are SFCC-132/225), so losing them here would be a
703	   * regression rather than a scope decision.
704	   *
705	   * ProductView calls this once per breakpoint, so it stays pure.
706	   */
707	  const renderStaticProductHeader = ({
708	    name,
709	    product: headerProduct,
710	    priceData,
711	    currency,
712	    category: headerCategory,
713	    isProductPartOfBundle,
714	  }: ProductViewHeaderProps) => {
715	    const info = selectPdpProductInfo(headerProduct ?? { name }, priceData, currency ?? '', formatPrice);
716	
717	    return (
718	      <VStack mr={4} spacing={2} align="flex-start" marginBottom={[4, 4, 4, 0, 0]}>
719	        {headerCategory && (
720	          <Skeleton isLoaded={headerCategory} minWidth={64}>
721	            <Breadcrumb categories={headerCategory} />
722	          </Skeleton>
723	        )}
724	
725	        <Skeleton isLoaded={Boolean(info)}>
726	          {info && (
727	            // h2, not h1: the page already emits a screen-reader-only
728	            // <h1>Product Details</h1>, and the base header this replaces rendered the name
729	            // as an h2. Changing the outline is SEO's call, not a side-effect of this ticket.
730	            <ZimmProductContent name={info.name} headingLevel="h2" price={info.price} description={info.description} />
731	          )}
732	        </Skeleton>
733	
734	        {!isProductPartOfBundle && (
735	          <Skeleton isLoaded={Boolean(headerProduct)}>
736	            {headerProduct?.productPromotions && <PromoCallout product={headerProduct} />}
737	          </Skeleton>
738	        )}
739	      </VStack>
740	    );
741	  };
742	
743	  // Model copy and the style code are not part of the content group: the design places them at
744	  // the foot of the column, below the accordions, so the page positions them itself.
745	  const staticInfo = selectPdpProductInfo(product, null, product?.currency ?? '', formatPrice);
746	
747	  return (
748	    <Box className="sf-product-detail-page" layerStyle="page" data-testid="product-details-page">
749	      <Heading as="h1" srOnly>
750	        <FormattedMessage defaultMessage="Product Details" id="product_detail.title.product_details" />
751	      </Heading>
752	      <Helmet>
753	        <title>{product?.pageTitle}</title>
754	        {product?.pageMetaTags?.length > 0 &&
755	          product.pageMetaTags.map(({ id, value }: { id: string; value: string }) => (
756	            <meta name={id} content={value} key={id} />
757	          ))}
758	        {/* Fallback for description if not included in pageMetaTags */}
759	        {!product?.pageMetaTags?.some((tag: { id: string }) => tag.id === 'description') &&
760	          product?.pageDescription && <meta name="description" content={product.pageDescription} />}
761	      </Helmet>
762	
763	      <Stack spacing={16}>
764	        {isProductASet || isProductABundle ? (
765	          <Fragment>
766	            <Island hydrateOn={'visible'}>
767	              <ProductView
768	                product={product}
769	                category={primaryCategory?.parentCategoryTree || []}
770	                addToCart={isProductASet ? handleProductSetAddToCart : handleProductBundleAddToCart}
771	                addToWishlist={handleAddToWishlist}
772	                isProductLoading={isProductLoading}
773	                isBasketLoading={isBasketLoading}
774	                isWishlistLoading={isWishlistLoading}
775	                validateOrderability={handleChildProductValidation}
776	                childProductOrderability={childProductOrderability}
777	                setSelectedBundleQuantity={setSelectedBundleQuantity}
778	                selectedBundleParentQuantity={selectedBundleQuantity}
779	                pickupInStore={!!pickupInStoreMap[product?.id]}
780	                setPickupInStore={(checked: boolean) => product && handlePickupInStoreChange(product.id, checked)}
781	                onOpenStoreLocator={onOpenStoreLocator}
782	                showDeliveryOptions={storeLocatorEnabled}
783	              />
784	            </Island>
785	
786	            <hr />
787	
788	            {
789	              // Render the child products
790	              product?.childProducts?.map(
791	                ({ product: childProduct, quantity: childQuantity }: { product: SfccProduct; quantity: number }) => (
792	                  <Box key={childProduct.id} data-testid="child-product">
793	                    <ProductView
794	                      // Do not use an arrow function as we are manipulating the functions scope.
795	                      // The assertion is unavoidable: ProductView rebinds `this` on a callback ref
796	                      // (see ProductViewRefScope) and React's own `Ref<T>` cannot express that.
797	                      ref={
798	                        function (this: ProductViewRefScope, ref: ChildProductRef['ref']) {
799	                          // Assign the "set" scope of the ref, this is how we access the internal
800	                          // validation.
801	                          childProductRefs.current[childProduct.id] = {
802	                            ref,
803	                            validateOrderability: this.validateOrderability,
804	                          };
805	                        } as unknown as React.Ref<HTMLDivElement>
806	                      }
807	                      product={childProduct}
808	                      isProductPartOfSet={isProductASet}
809	                      isProductPartOfBundle={isProductABundle}
810	                      childOfBundleQuantity={childQuantity}
811	                      selectedBundleParentQuantity={selectedBundleQuantity}
812	                      addToCart={
813	                        isProductASet
814	                          ? (productSelectionValues: ProductSelectionValue[]) => handleAddToCart(productSelectionValues)
815	                          : null
816	                      }
817	                      addToWishlist={isProductASet ? handleAddToWishlist : null}
818	                      onVariantSelected={(product: SfccProduct, variant: SfccVariant, quantity: number) => {
819	                        if (quantity) {
820	                          setChildProductSelection((previousState) => ({
821	                            ...previousState,
822	                            [product.id]: {
823	                              product,
824	                              variant,
825	                              quantity: isProductABundle ? childQuantity : quantity,
826	                            },
827	                          }));
828	                        } else {
829	                          const selections = {
830	                            ...childProductSelection,
831	                          };
832	                          delete selections[product.id];
833	                          setChildProductSelection(selections);
834	                        }
835	                      }}
836	                      isProductLoading={isProductLoading}
837	                      isBasketLoading={isBasketLoading}
838	                      isWishlistLoading={isWishlistLoading}
839	                      setChildProductOrderability={setChildProductOrderability}
840	                      pickupInStore={!!pickupInStoreMap[childProductSelection[childProduct?.id]?.variant?.productId]}
841	                      setPickupInStore={(checked: boolean) =>
842	                        childProduct &&
843	                        handlePickupInStoreChange(childProductSelection[childProduct?.id]?.variant?.productId, checked)
844	                      }
845	                      onOpenStoreLocator={onOpenStoreLocator}
846	                      showDeliveryOptions={storeLocatorEnabled && !isProductABundle}
847	                    />
848	                    <InformationAccordion product={childProduct} />
849	
850	                    <Box display={['none', 'none', 'none', 'block']}>
851	                      <hr />
852	                    </Box>
853	                  </Box>
854	                ),
855	              )
856	            }
857	          </Fragment>
858	        ) : (
859	          <Fragment>
860	            <Island hydrateOn={'visible'}>
861	              <ProductView
862	                product={product}
863	                category={primaryCategory?.parentCategoryTree || []}
864	                renderHeader={renderStaticProductHeader}
865	                addToCart={handleAddToCart}
866	                addToWishlist={handleAddToWishlist}
867	                isProductLoading={isProductLoading}
868	                isBasketLoading={isBasketLoading}
869	                isWishlistLoading={isWishlistLoading}
870	                childProductOrderability={childProductOrderability}
871	                setChildProductOrderability={setChildProductOrderability}
872	                setSelectedBundleQuantity={setSelectedBundleQuantity}
873	                selectedBundleParentQuantity={selectedBundleQuantity}
874	                pickupInStore={!!pickupInStoreMap[product?.id]}
875	                setPickupInStore={(checked: boolean) => product && handlePickupInStoreChange(product.id, checked)}
876	                onOpenStoreLocator={onOpenStoreLocator}
877	                showDeliveryOptions={storeLocatorEnabled}
878	              />
879	              <InformationAccordion product={product} />
880	
881	              <Stack spacing="l" paddingTop="l">
882	                <ZimmProductModelInfo modelInfo={staticInfo?.modelInfo} />
883	                <ZimmProductStyleCode value={staticInfo?.styleCode} />
884	              </Stack>
885	            </Island>
886	          </Fragment>
887	        )}
888	
889	        {/* Product Recommendations */}
890	        <Stack spacing={16}>
891	          {!isProductASet && (
892	            <Island hydrateOn={'visible'}>
893	              <RecommendedProducts
894	                title={
895	                  <FormattedMessage
896	                    defaultMessage="Complete the Set"
897	                    id="product_detail.recommended_products.title.complete_set"
898	                  />
899	                }
900	                recommender={EINSTEIN_RECOMMENDERS.PDP_COMPLETE_SET}
901	                products={[product]}
902	                mx={{ base: -4, md: -8, lg: 0 }}
903	                shouldFetch={() => product?.id}
904	              />
905	            </Island>
906	          )}
907	          <Island hydrateOn={'visible'}>
908	            <RecommendedProducts
909	              title={
910	                <FormattedMessage
911	                  defaultMessage="You might also like"
912	                  id="product_detail.recommended_products.title.might_also_like"
913	                />
914	              }
915	              recommender={EINSTEIN_RECOMMENDERS.PDP_MIGHT_ALSO_LIKE}
916	              products={[product]}
917	              mx={{ base: -4, md: -8, lg: 0 }}
918	              shouldFetch={() => product?.id}
919	            />
920	          </Island>
921	
922	          <Island hydrateOn={'visible'}>
923	            <RecommendedProducts
924	              // The Recently Viewed recommender doesn't use `products`, so instead we
925	              // provide a key to update the recommendations on navigation.
926	              key={location.key}
927	              title={
928	                <FormattedMessage
929	                  defaultMessage="Recently Viewed"
930	                  id="product_detail.recommended_products.title.recently_viewed"
931	                />
932	              }
933	              recommender={EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED}
934	              mx={{ base: -4, md: -8, lg: 0 }}
935	            />
936	          </Island>
937	        </Stack>
938	      </Stack>
939	    </Box>
940	  );
941	};
942	
943	ProductDetail.getTemplateName = () => 'product-detail';
944	
945	/*
946	 * The base file declares `ProductDetail.propTypes = {match: PropTypes.object}` purely as
947	 * documentation — the component takes no props and never reads `match`. The TypeScript
948	 * signature above expresses the same thing at compile time, so the runtime `prop-types`
949	 * declaration is not carried over.
950	 */
951	
952	export default ProductDetail;
953

