72	
73	/*
74	 * `@salesforce/retail-react-app` ships no TypeScript types (see
75	 * overrides/app/types/vendor.d.ts). These aliases name that gap once rather than spreading
76	 * bare `any` through the file; narrow them as the real shapes are confirmed.
77	 */
78	type SfccProduct = any;
79	type SfccVariant = any;
80	type SfccCategory = any;
81	type SfccPriceData = any;
82	
83	/** One selectable value of a variation attribute, as the base hooks shape it. */
84	type SfccVariationValue = { href?: string; name: string; image?: SfccProduct; value?: string; orderable?: boolean };
85	
86	/** A variation attribute (colour, size, ...) with its selectable values. */
87	type SfccVariationAttribute = {
88	  id: string;
89	  name?: string;
90	  selectedValue?: SfccVariationValue;
91	  values: SfccVariationValue[];
92	};
93	
94	/** The per-child orderability record ProductView writes back to its parent. */
95	export type ChildProductOrderability = {
96	  showInventoryMessage?: boolean;
97	  unfulfillable?: boolean;
98	  isOutOfStock?: boolean;
99	  stockLevel?: number;
100	  productName?: string;
101	};
102	
103	export type ProductViewHeaderProps = {
104	  name?: string;
105	  currency?: string;
106	  priceData?: SfccPriceData;
107	  category?: SfccCategory[];
108	  product?: SfccProduct;
109	  isProductPartOfBundle?: boolean;
110	};
111	
112	/*
113	 * Mirrors the base file's `ProductView.propTypes` one-for-one, with the defaults declared in
114	 * the destructuring below reflected as optional. `validateOrderability`'s signature is taken
115	 * from the default implementation the base file supplies.
116	 */
117	type ProductViewProps = {
118	  product?: SfccProduct;
119	  category?: SfccCategory[];
120	  showFullLink?: boolean;
121	  imageSize?: 'sm' | 'md';
122	  isWishlistLoading?: boolean;
123	  addToCart?: ((productSelectionValues: SfccProduct[]) => unknown) | null;
124	  updateCart?: ((variant: SfccVariant, quantity: number) => unknown) | null;
125	  addToWishlist?: ((product: SfccProduct, variant: SfccVariant, quantity: number) => unknown) | null;
126	  updateWishlist?: ((product: SfccProduct, variant: SfccVariant, quantity: number) => unknown) | null;
127	  isProductLoading?: boolean;
128	  isProductPartOfSet?: boolean;
129	  isProductPartOfBundle?: boolean;
130	  childOfBundleQuantity?: number;
131	  childProductOrderability?: Record<string, ChildProductOrderability>;
132	  setChildProductOrderability?: React.Dispatch<React.SetStateAction<Record<string, ChildProductOrderability>>>;
133	  isBasketLoading?: boolean;
134	  onVariantSelected?: (product: SfccProduct, variant: SfccVariant, quantity: number) => void;
135	  validateOrderability?: (
136	    variant: SfccVariant,
137	    product: SfccProduct,
138	    quantity: number,
139	    stockLevel: number,
140	  ) => boolean | undefined;
141	  showImageGallery?: boolean;
142	  setSelectedBundleQuantity?: (quantity: number) => void;
143	  selectedBundleParentQuantity?: number;
144	  pickupInStore?: boolean;
145	  setPickupInStore?: (checked: boolean) => void;
146	  onOpenStoreLocator?: () => void;
147	  showDeliveryOptions?: boolean;
148	  customButtons?: React.ReactElement[];
149	  maxOrderQuantity?: number | null;
150	  imageGalleryFooter?: React.ReactNode;
151	  controlledVariationValues?: Record<string, string> | null;
152	  onVariationChange?: ((attributeId: string, value: string) => void) | null;
153	  /**
154	   * The one Zimmermann addition to this component's prop surface. Replaces the header block
155	   * (breadcrumb, title, price, promo callout) with caller-supplied content, receiving exactly
156	   * the values the private `ProductViewHeader` is given so a caller can reuse or ignore any of
157	   * them. Defaults to rendering that same private header, so every existing caller — cart,
158	   * wishlist, bonus-product — is byte-identical unless it opts in.
159	   *
160	   * ProductView renders the header twice (mobile and desktop breakpoints), so this is called
161	   * twice with the same arguments. Keep it pure.
162	   */
163	  renderHeader?: (props: ProductViewHeaderProps) => React.ReactNode;
164	};
165	
166	/*
167	 * The base file rebinds a function ref's `this` so the parent can reach `validateOrderability`
168	 * (see the `typeof ref === 'function'` branch below, and the set/bundle child refs in
169	 * pages/product-detail).
170	 */
171	type ProductViewRef = React.ForwardedRef<HTMLDivElement>;
172	
173	/**
174	 * The scope ProductView rebinds onto a callback `ref`, so a parent rendering set/bundle
175	 * children can reach this instance's validation. See the `typeof ref === 'function'` branch
176	 * below — React's own `Ref<T>` type cannot express a `this`-bound callback, so consumers
177	 * assert against this type at the prop site.
178	 */
179	export type ProductViewRefScope = {
180	  validateOrderability: (opts: { scrollErrorIntoView: boolean }) => void;
181	};
182	
183	const ProductViewHeader = ({
184	  name,
185	  currency,
186	  priceData,
187	  category,
188	  product,
189	  isProductPartOfBundle,
190	}: ProductViewHeaderProps) => {
191	  return (
192	    <VStack mr={4} spacing={2} align="flex-start" marginBottom={[4, 4, 4, 0, 0]}>
193	      {category && (
194	        <Skeleton isLoaded={category} minWidth={64}>
195	          <Breadcrumb categories={category} />
196	        </Skeleton>
197	      )}
198	
199	      {/* Title */}
200	      <Skeleton isLoaded={name}>
201	        <Heading fontSize="2xl">{`${name}`}</Heading>
202	      </Skeleton>
203	
204	      {!isProductPartOfBundle && (
205	        <>
206	          <Skeleton isLoaded={priceData?.currentPrice}>
207	            {priceData?.currentPrice && <DisplayPrice priceData={priceData} currency={currency} />}
208	          </Skeleton>
209	
210	          <Skeleton isLoaded={product}>{product?.productPromotions && <PromoCallout product={product} />}</Skeleton>
211	        </>
212	      )}
213	    </VStack>
214	  );
215	};
216	
217	const ButtonWithRegistration = withRegistration(Button);
218	
219	/**
220	 * Render a product detail view that includes name, image gallery, price,
221	 * variant selections, action buttons
222	 */
223	
224	const ProductView = forwardRef(
225	  (
226	    {
227	      product,
228	      category,
229	      showFullLink = false,
230	      imageSize = 'md',
231	      isWishlistLoading = false,
232	      addToCart,
233	      updateCart,
234	      addToWishlist,
235	      updateWishlist,
236	      isProductLoading,
237	      isProductPartOfSet = false,
238	      isProductPartOfBundle = false,
239	      childOfBundleQuantity = 0,
240	      childProductOrderability,
241	      setChildProductOrderability,
242	      isBasketLoading = false,
243	      onVariantSelected = () => {},
244	      validateOrderability = (variant, product, quantity, stockLevel) => {
245	        if (isProductLoading) return false;
246	
247	        // If product has variations, a variant must be selected
248	        if (product?.variationAttributes?.length > 0 && !variant) {
249	          return false;
250	        }
251	
252	        // Check if product (either variant or standard) is orderable and if quantity is valid
253	        return (variant?.orderable || product?.inventory?.orderable) && quantity > 0 && quantity <= stockLevel;
254	      },
255	      showImageGallery = true,
256	      setSelectedBundleQuantity = () => {},
257	      selectedBundleParentQuantity = 1,
258	      pickupInStore = false,
259	      setPickupInStore = () => {},
260	      onOpenStoreLocator = () => {},
261	      showDeliveryOptions = true,
262	      customButtons = [],
263	      maxOrderQuantity = null,
264	      imageGalleryFooter = null,
265	      controlledVariationValues = null,
266	      onVariationChange = null,
267	      renderHeader = (headerProps: ProductViewHeaderProps) => <ProductViewHeader {...headerProps} />,
268	    }: ProductViewProps,
269	    ref: ProductViewRef,
270	  ) => {
271	    const { currency: activeCurrency } = useCurrency();
272	    const showToast = useToast();
273	    const intl = useIntl();
274	    const location = useLocation();
275	    const storeLocatorEnabled = getConfig()?.app?.storeLocatorEnabled ?? STORE_LOCATOR_IS_ENABLED;
276	    const {
277	      isOpen: isAddToCartModalOpen,
278	      onOpen: onAddToCartModalOpen,
279	      onClose: onAddToCartModalClose,
280	    } = useAddToCartModalContext();
281	
282	    const { mutateAsync: createBasket } = useShopperBasketsMutation('createBasket');
283	    const { mutateAsync: addItemToBasket } = useShopperBasketsMutation('addItemToBasket');
284	
285	    const theme = useTheme();
286	    const { confirmingBasket } = useSFPayments();
287	    const [showOptionsMessage, toggleShowOptionsMessage] = useState(false);
288	    const {
289	      showLoading,
290	      showInventoryMessage,
291	      inventoryMessage,
292	      quantity,
293	      minOrderQuantity,
294	      setQuantity,
295	      variant,
296	      variationParams,
297	      variationAttributes,
298	      stockLevel,
299	      stepQuantity,
300	      isOutOfStock,
301	      unfulfillable,
302	      isSelectedStoreOutOfStock,
303	      selectedStore,
304	    } = useDerivedProduct(
305	      product,
306	      isProductPartOfSet,
307	      isProductPartOfBundle,
308	      pickupInStore,
309	      controlledVariationValues,
310	      onVariationChange,
311	    );
312	    const priceData = useMemo(() => {
313	      return getPriceData(product, { quantity });
314	    }, [product, quantity]);
315	    const canAddToWishlist = !isProductLoading;
316	    const isProductASet = product?.type?.set;
317	    const isProductABundle = product?.type?.bundle;
318	    const errorContainerRef = useRef<HTMLDivElement | null>(null);
319	    const [pickupEnabled, setPickupEnabled] = useState(false);
320	    const storeName = selectedStore?.name;
321	    const inventoryId = selectedStore?.inventoryId;
322	    const { pdp: showExpressOnPDP } = useExpressCheckoutEnabled();
323	
324	    const { disableButton, customInventoryMessage } = useMemo(() => {
325	      let shouldDisableButton = showInventoryMessage;
326	      let currentInventoryMsg = '';
327	      if (!shouldDisableButton && (isProductASet || isProductABundle) && childProductOrderability) {
328	        // if any of the children are not orderable, it will disable the add to cart button
329	        const unavailableChildProductKey = Object.keys(childProductOrderability).find((key) => {
330	          return childProductOrderability[key].showInventoryMessage;
331	        });
332	        shouldDisableButton = !!unavailableChildProductKey;
333	        if (unavailableChildProductKey) {
334	          const unavailableChildProduct = childProductOrderability[unavailableChildProductKey];
335	          if (unavailableChildProduct.unfulfillable) {
336	            currentInventoryMsg = intl.formatMessage(
337	              {
338	                defaultMessage: 'Only {stockLevel} left for {productName}!',
339	                id: 'use_product.message.inventory_remaining_for_product',
340	              },
341	              {
342	                stockLevel: unavailableChildProduct.stockLevel,
343	                productName: unavailableChildProduct.productName,
344	              },
345	            );
346	          }
347	          if (unavailableChildProduct.isOutOfStock) {
348	            currentInventoryMsg = intl.formatMessage(
349	              {
350	                defaultMessage: 'Out of stock for {productName}',
351	                id: 'use_product.message.out_of_stock_for_product',
352	              },
353	              { productName: unavailableChildProduct.productName },
354	            );
355	          }
356	        }
357	      }
358	      return { disableButton: shouldDisableButton, customInventoryMessage: currentInventoryMsg };
359	    }, [showInventoryMessage, childProductOrderability]);
360	
361	    const validateAndShowError = (opts: { scrollErrorIntoView?: boolean } = {}) => {
362	      const { scrollErrorIntoView = true } = opts;
363	      // Validate that all attributes are selected before proceeding.
364	      const hasValidSelection = validateOrderability(variant, product, quantity, stockLevel);
365	      const showError = !isProductASet && !isProductABundle && !hasValidSelection;
366	      const scrollToError = showError && scrollErrorIntoView;
367	
368	      toggleShowOptionsMessage(showError);
369	
370	      if (scrollToError) {
371	        // Deviation from the base file: `?.`. The base dereferences `current` unguarded here
372	        // while guarding it in `prepareBasket` below; the two only differ if the error
373	        // container has not mounted, where the base throws.
374	        errorContainerRef.current?.scrollIntoView({
375	          behavior: 'smooth',
376	          block: 'center',
377	        });
378	      }
379	
380	      return hasValidSelection;
381	    };
382	    const cleanupTemporaryBaskets = useCleanupTemporaryBaskets();
383	
384	    // prepareBasket is used to prepare the basket for express payments
385	    // useCallback recreates prepareBasket primarily when product or quantity change, along with variant, stockLevel, and product type flags (isProductASet, isProductABundle)
386	    const prepareBasket = useCallback(async () => {
387	      // Validate that all attributes are selected before proceeding
388	      const hasValidSelection = validateOrderability(variant, product, quantity, stockLevel);
389	      let errorMessage = '';
390	
391	      if (!hasValidSelection && !isProductASet && !isProductABundle) {
392	        toggleShowOptionsMessage(true);
393	        if (errorContainerRef.current) {
394	          errorContainerRef.current.scrollIntoView({
395	            behavior: 'smooth',
396	            block: 'center',
397	          });
398	        }
399	        errorMessage = intl.formatMessage({
400	          defaultMessage: 'Please select all product options before proceeding with Express Payments',
401	          id: 'product_view.prepareBasket',
402	        });
403	
404	        const error: Error & { isValidationError?: boolean } = new Error(errorMessage);
405	        error.isValidationError = true;
406	        throw error;
407	      }
408	
409	      // Clean up temporary baskets before creating a new one
410	      await cleanupTemporaryBaskets();
411	
412	      // Create a new temporary basket
413	      const newBasket = await createBasket({
414	        parameters: {
415	          temporary: true,
416	        },
417	        body: {},
418	      });
419	
420	      const selectedProduct = variant || product;
421	      // Use variant's productId if variant is selected, otherwise use product's id
422	      const productIdToUse = selectedProduct?.productId || selectedProduct?.id;
423	
424	      if (!productIdToUse) {
425	        errorMessage = intl.formatMessage({
426	          defaultMessage: 'Unable to determine product ID for basket',
427	          id: 'product_view.prepareBasket',
428	        });
429	        throw new Error(errorMessage);
430	      }
431	      // Add the product to the temporary basket
432	      const basketWithItem = await addItemToBasket({
433	        // SDK param widening — `newBasket` is the basket just created above.
434	        parameters: { basketId: newBasket.basketId as string },
435	        body: [
436	          {
437	            productId: productIdToUse,
438	            quantity: quantity,
439	          },
440	        ],
441	      });
442	
443	      return basketWithItem;
444	    }, [variant, product, quantity, stockLevel, isProductASet, isProductABundle]);
445	
446	    const renderActionButtons = () => {
447	      const buttons = [];
448	      const buttonText = {
449	        update: intl.formatMessage({
450	          defaultMessage: 'Update',
451	          id: 'product_view.button.update',
452	        }),
453	        addToCart: intl.formatMessage({
454	          defaultMessage: 'Add to Cart',
455	          id: 'product_view.button.add_to_cart',
456	        }),
457	        addSetToCart: intl.formatMessage({
458	          defaultMessage: 'Add Set to Cart',
459	          id: 'product_view.button.add_set_to_cart',
460	        }),
461	        addBundleToCart: intl.formatMessage({
462	          defaultMessage: 'Add Bundle to Cart',
463	          id: 'product_view.button.add_bundle_to_cart',
464	        }),
465	        addToWishlist: intl.formatMessage({
466	          defaultMessage: 'Add to Wishlist',
467	          id: 'product_view.button.add_to_wishlist',
468	        }),
469	        addSetToWishlist: intl.formatMessage({
470	          defaultMessage: 'Add Set to Wishlist',
471	          id: 'product_view.button.add_set_to_wishlist',
472	        }),
473	        addBundleToWishlist: intl.formatMessage({
474	          defaultMessage: 'Add Bundle to Wishlist',
475	          id: 'product_view.button.add_bundle_to_wishlist',
476	        }),
477	      };
478	
479	      const showError = () => {
480	        showToast({
481	          title: intl.formatMessage(API_ERROR_MESSAGE),
482	          status: 'error',
483	        });
484	      };
485	
486	      const handleCartItem = async () => {
487	        const hasValidSelection = validateAndShowError();
488	
489	        if (!hasValidSelection) {
490	          return null;
491	        }
492	
493	        if (!addToCart && !updateCart) return null;
494	        if (updateCart) {
495	          await updateCart(variant || product, quantity);
496	          return;
497	        }
498	        try {
499	          // Guarded above: `!addToCart && !updateCart` returns early, and the `updateCart`
500	          // branch returns, so `addToCart` is defined here. TypeScript cannot narrow across
501	          // those two statements.
502	          const itemsAdded = await addToCart!([{ product, variant, quantity }]);
503	          // Open modal only when `addToCart` returns some data
504	          // It's possible that the item has been added to cart, but we don't want to open the modal.
505	          // See wishlist_primary_action for example.
506	          if (itemsAdded) {
507	            onAddToCartModalOpen({
508	              product,
509	              itemsAdded,
510	              selectedQuantity: quantity,
511	            });
512	          }
513	        } catch (e) {
514	          showError();
515	        }
516	      };
517	
518	      const handleWishlistItem = async () => {
519	        if (!updateWishlist && !addToWishlist) return null;
520	        if (updateWishlist) {
521	          updateWishlist(product, variant, quantity);
522	          return;
523	        }
524	        // Guarded above, exactly as `addToCart` is in handleCartItem.
525	        addToWishlist!(product, variant, quantity);
526	      };
527	
528	      // child product of bundles do not have add to cart button
529	      if ((addToCart || updateCart) && !isProductPartOfBundle) {
530	        buttons.push(
531	          <Button
532	            key="cart-button"
533	            onClick={handleCartItem}
534	            isDisabled={disableButton}
535	            isLoading={isBasketLoading}
536	            width="100%"
537	            variant="solid"
538	            marginBottom={4}
539	          >
540	            {updateCart
541	              ? buttonText.update
542	              : isProductASet
543	              ? buttonText.addSetToCart
544	              : isProductABundle
545	              ? buttonText.addBundleToCart
546	              : buttonText.addToCart}
547	          </Button>,
548	        );
549	      }
550	
551	      // child product of bundles do not have add to wishlist button
552	      if ((addToWishlist || updateWishlist) && !isProductPartOfBundle) {
553	        buttons.push(
554	          <ButtonWithRegistration
555	            key="wishlist-button"
556	            onClick={handleWishlistItem}
557	            disabled={isWishlistLoading || !canAddToWishlist}
558	            isLoading={isWishlistLoading}
559	            width="100%"
560	            variant="outline"
561	            marginBottom={4}
562	          >
563	            {updateWishlist
564	              ? buttonText.update
565	              : isProductASet
566	              ? buttonText.addSetToWishlist
567	              : isProductABundle
568	              ? buttonText.addBundleToWishlist
569	              : buttonText.addToWishlist}
570	          </ButtonWithRegistration>,
571	        );
572	      }
573	
574	      if (showExpressOnPDP && !isProductASet && !isProductPartOfBundle && activeCurrency && priceData.currentPrice) {
575	        buttons.push(
576	          <SFPaymentsExpressButtons
577	            key="express-buttons"
578	            usage={EXPRESS_BUY_NOW}
579	            paymentCurrency={activeCurrency}
580	            paymentCountryCode={null}
581	            initialAmount={priceData.currentPrice}
582	            prepareBasket={prepareBasket}
583	            expressButtonLayout="vertical"
584	            maximumButtonCount={1}
585	          />,
586	        );
587	      }
588	
589	      // Add custom buttons if provided
590	      if (customButtons && customButtons.length > 0) {
591	        customButtons.forEach((customButton, index) => {
592	          buttons.push(
593	            React.cloneElement(customButton, {
594	              key: `custom-button-${index}`,
595	              width: (customButton.props as { width?: string }).width || '100%',
596	              marginBottom: (customButton.props as { marginBottom?: number }).marginBottom || 4,
597	            } as Partial<unknown> & React.Attributes),
598	          );
599	        });
600	      }
601	
602	      return buttons;
603	    };
604	
605	    // Bind the reference with our `scope` that includes the internal validate function for this component.
606	    // Other values can be added to this scope as required.
607	    if (typeof ref === 'function') {
608	      ref = ref.bind({ validateOrderability: validateAndShowError });
609	    }
610	
611	    // Set the quantity of bundle child in a product bundle to ensure availability messages appear
612	    if (isProductPartOfBundle && quantity != selectedBundleParentQuantity * childOfBundleQuantity) {
613	      setQuantity(selectedBundleParentQuantity * childOfBundleQuantity);
614	    }
615	
616	    useEffect(() => {
617	      if (isAddToCartModalOpen) {
618	        onAddToCartModalClose();
619	      }
620	    }, [location.pathname]);
621	
622	    useEffect(() => {
623	      if (!isProductASet && !isProductABundle && validateOrderability(variant, product, quantity, stockLevel)) {
624	        toggleShowOptionsMessage(false);
625	      }
626	    }, [variationParams]);
627	
628	    useEffect(() => {
629	      if (variant) {
630	        onVariantSelected(product, variant, quantity);
631	      }
632	    }, [variant?.productId, quantity]);
633	
634	    useEffect(() => {
635	      if ((isProductPartOfBundle || isProductPartOfSet) && product && product.type?.item) {
636	        onVariantSelected(product, null, childOfBundleQuantity || quantity);
637	      }
638	    }, [product, childOfBundleQuantity, quantity, isProductPartOfBundle, isProductPartOfSet]);
639	
640	    useEffect(() => {
641	      if (isProductPartOfBundle || isProductPartOfSet) {
642	        const key = product.itemId ?? product.id;
643	        // when showInventoryMessage is true, it means child product is not orderable
644	        // Deviation from the base file: optional call. The prop has no default, and the base
645	        // calls it unguarded — only reachable for set/bundle children, whose parent always
646	        // supplies it.
647	        setChildProductOrderability?.((previousState) => ({
648	          ...previousState,
649	          [key]: {
650	            showInventoryMessage,
651	            isOutOfStock,
652	            unfulfillable,
653	            stockLevel,
654	            productName: product?.name,
655	          },
656	        }));
657	      }
658	    }, [showInventoryMessage, inventoryMessage]);
659	
660	    // Auto-switch off pickup in store when product becomes unavailable at selected store
661	    useEffect(() => {
662	      setPickupEnabled(!!selectedStore?.inventoryId);
663	      if (pickupInStore && isSelectedStoreOutOfStock) {
664	        setPickupInStore(false);
665	      }
666	    }, [selectedStore]);
667	
668	    const handleDeliveryOptionChange = (value: string) => {
669	      setPickupInStore(value === DELIVERY_OPTIONS.PICKUP);
670	    };
671	
672	    return (
673	      <Flex direction={'column'} data-testid="product-view" ref={ref}>
674	        {/* Basic information etc. title, price, breadcrumb*/}
675	        <Box display={['block', 'block', 'block', 'none']}>
676	          {renderHeader({
677	            name: product?.name,
678	            product,
679	            priceData,
680	            currency: product?.currency || activeCurrency,
681	            category,
682	            isProductPartOfBundle,
683	          })}
684	        </Box>
685	        <Flex direction={['column', 'column', 'column', 'row']}>
686	          {showImageGallery && (
687	            <Box flex={1} mr={[0, 0, 0, 6, 6]}>
688	              {product ? (
689	                <>
690	                  <ImageGallery
691	                    size={imageSize}
692	                    imageGroups={product.imageGroups}
693	                    selectedVariationAttributes={variationParams}
694	                    lazy={isProductPartOfSet || isProductPartOfBundle}
695	                  />
696	                  <HideOnMobile>
697	                    {showFullLink && product && (
698	                      <Link to={`/product/${product.master.masterId}`} color="blue.600">
699	                        <FormattedMessage id="product_view.link.full_details" defaultMessage="See full details" />
700	                      </Link>
701	                    )}
702	                  </HideOnMobile>
703	                </>
704	              ) : (
705	                <ImageGallerySkeleton />
706	              )}
707	              {/* Custom footer content (e.g., Back to Selection button) */}
708	              {imageGalleryFooter && (
709	                <Box mt={6} mb={2}>
710	                  {imageGalleryFooter}
711	                </Box>
712	              )}
713	            </Box>
714	          )}
715	
716	          {/* Variations & Quantity Selector & CTA buttons */}
717	          <VStack
718	            align="stretch"
719	            spacing={8}
720	            flex={1}
721	            pb={[
722	              isProductPartOfSet || isProductPartOfBundle ? 4 : '120px',
723	              isProductPartOfSet || isProductPartOfBundle ? 4 : '120px',
724	              isProductPartOfSet || isProductPartOfBundle ? 4 : '120px',
725	              4,
726	            ]}
727	          >
728	            <Box display={['none', 'none', 'none', 'block']}>
729	              {renderHeader({
730	                name: product?.name,
731	                product,
732	                priceData,
733	                currency: product?.currency || activeCurrency,
734	                category,
735	                isProductPartOfBundle,
736	              })}
737	            </Box>
738	            <VStack align="stretch" spacing={4}>
739	              {isProductPartOfBundle && (
740	                <Box>
741	                  <Text fontWeight="medium" fontSize="md" aria-label="price">
742	                    <label>
743	                      {intl.formatMessage({
744	                        defaultMessage: 'Quantity',
745	                        id: 'product_view.label.quantity',
746	                      })}
747	                      : {childOfBundleQuantity}
748	                    </label>
749	                  </Text>
750	                </Box>
751	              )}
752	              {/*
753	                                Customize the skeletons shown for attributes to suit your needs. At the point
754	                                that we show the skeleton we do not know how many variations are selectable. So choose
755	                                a a skeleton that will meet most of your needs.
756	                            */}
757	              {showLoading ? (
758	                <>
759	                  {/* First Attribute Skeleton */}
760	                  <Skeleton height={6} width={32} />
761	                  <Skeleton height={20} width={64} />
762	
763	                  {/* Second Attribute Skeleton */}
764	                  <Skeleton height={6} width={32} />
765	                  <Skeleton height={20} width={64} />
766	                </>
767	              ) : (
768	                variationAttributes.map(({ id, name, selectedValue, values }: SfccVariationAttribute) => {
769	                  const swatches = values.map(
770	                    ({ href, name, image, value, orderable }: SfccVariationValue, index: number) => {
771	                      const content = image ? (
772	                        <Box
773	                          height="100%"
774	                          width="100%"
775	                          minWidth="32px"
776	                          backgroundRepeat="no-repeat"
777	                          backgroundSize="cover"
778	                          backgroundColor={name.toLowerCase()}
779	                          backgroundImage={`url(${image.disBaseLink || image.link})`}
780	                        />
781	                      ) : (
782	                        name
783	                      );
784	                      const hasSelection = Boolean(selectedValue?.value);
785	                      const isSelected = selectedValue?.value === value;
786	                      const isFirst = index === 0;
787	                      // To mimic the behavior of a native radio input, only
788	                      // one swatch should receive tab focus; the rest can be
789	                      // selected using arrow keys when the swatch group has
790	                      // focus. The focused element is the selected option or
791	                      // the first in the group, if no option is selected.
792	                      // This is a slight difference, for simplicity, from the
793	                      // native element, where the first element is focused on
794	                      // `Tab` and the _last_ element is focused on `Shift+Tab`
795	                      const isFocusable = isSelected || (!hasSelection && isFirst);
796	                      return (
797	                        <Swatch
798	                          key={value}
799	                          href={href}
800	                          disabled={!orderable}
801	                          value={value}
802	                          name={name}
803	                          variant={id === 'color' ? 'circle' : 'square'}
804	                          selected={isSelected}
805	                          isFocusable={isFocusable}
806	                        >
807	                          {content}
808	                        </Swatch>
809	                      );
810	                    },
811	                  );
812	                  return (
813	                    <SwatchGroup
814	                      key={id}
815	                      value={selectedValue?.value}
816	                      displayName={selectedValue?.name || ''}
817	                      label={intl.formatMessage(
818	                        {
819	                          defaultMessage: '{variantType}',
820	                          id: 'product_view.label.variant_type',
821	                        },
822	                        { variantType: name },
823	                      )}
824	                      handleChange={onVariationChange ? (value: string) => onVariationChange(id, value) : undefined}
825	                    >
826	                      {swatches}
827	                    </SwatchGroup>
828	                  );
829	                })
830	              )}
831	
832	              {!isProductASet && !isProductPartOfBundle && (
833	                <VStack align="stretch" maxWidth={'200px'}>
834	                  <Box fontWeight="bold">
835	                    <label htmlFor="quantity">
836	                      {intl.formatMessage({
837	                        defaultMessage: 'Quantity:',
838	                        id: 'product_view.label.quantity',
839	                      })}
840	                    </label>
841	                  </Box>
842	
843	                  <QuantityPicker
844	                    id="quantity"
845	                    step={stepQuantity}
846	                    value={quantity}
847	                    min={minOrderQuantity}
848	                    {...(maxOrderQuantity != null && { max: maxOrderQuantity })}
849	                    onChange={(stringValue: string, numberValue: number) => {
850	                      // Set the Quantity of product to value of input if value number
851	                      if (numberValue >= 0) {
852	                        setQuantity(numberValue);
853	                        if (isProductABundle) setSelectedBundleQuantity(numberValue);
854	                      } else if (stringValue === '') {
855	                        // We want to allow the use to clear the input to start a new input so here we set the quantity to '' so NAN is not displayed
856	                        // User will not be able to add '' qauntity to the cart due to the add to cart button enablement rules
857	                        setQuantity(stringValue);
858	                      }
859	                    }}
860	                    onBlur={(e: React.FocusEvent<HTMLInputElement>) => {
861	                      // Default to 1the `minOrderQuantity` if a user leaves the box with an invalid value
862	                      const value = e.target.value;
863	                      if (parseInt(value) < 0 || value === '') {
864	                        setQuantity(minOrderQuantity);
865	                        if (isProductABundle) setSelectedBundleQuantity(minOrderQuantity);
866	                      }
867	                    }}
868	                    onFocus={(e: React.FocusEvent<HTMLInputElement>) => {
869	                      // This is useful for mobile devices, this allows the user to pop open the keyboard and set the
870	                      // new quantity with one click. NOTE: This is something that can be refactored into the parent
871	                      // component, potentially as a prop called `selectInputOnFocus`.
872	                      e.target.select();
873	                    }}
874	                    productName={product?.name}
875	                  />
876	                </VStack>
877	              )}
878	              <Box ref={errorContainerRef}>
879	                {!showLoading && showOptionsMessage && (
880	                  <Fade in={true}>
881	                    <Text color="orange.600" fontWeight={600} marginBottom={8}>
882	                      {intl.formatMessage({
883	                        defaultMessage: 'Please select all your options above',
884	                      })}
885	                    </Text>
886	                  </Fade>
887	                )}
888	              </Box>
889	              <HideOnDesktop>
890	                {showFullLink && product && (
891	                  <Link to={`/product/${product.master.masterId}`} color="blue.600">
892	                    <FormattedMessage id="product_view.link.full_details" defaultMessage="See full details" />
893	                  </Link>
894	                )}
895	              </HideOnDesktop>
896	              {isProductASet && <p>{product?.shortDescription}</p>}
897	            </VStack>
898	
899	            <Box>
900	              {!showLoading && showInventoryMessage && !customInventoryMessage && (
901	                <Fade in={true}>
902	                  <Text color="orange.600" fontWeight={600} marginBottom={8}>
903	                    {inventoryMessage}
904	                  </Text>
905	                </Fade>
906	              )}
907	              {!showLoading && customInventoryMessage && (
908	                <Fade in={true}>
909	                  <Text color="orange.600" fontWeight={600} marginBottom={8}>
910	                    {customInventoryMessage}
911	                  </Text>
912	                </Fade>
913	              )}
914	              <Box>
915	                {showDeliveryOptions && (
916	                  <>
917	                    <Box mb={4}>
918	                      <Text fontWeight={600} mb={3}>
919	                        <FormattedMessage defaultMessage="Delivery:" id="product_view.label.delivery" />
920	                      </Text>
921	                      <RadioGroup
922	                        value={pickupInStore ? DELIVERY_OPTIONS.PICKUP : DELIVERY_OPTIONS.DELIVERY}
923	                        onChange={handleDeliveryOptionChange}
924	                        mb={1}
925	                      >
926	                        <Stack direction="column" spacing={2}>
927	                          <Radio value={DELIVERY_OPTIONS.DELIVERY} isDisabled={disableButton}>
928	                            <FormattedMessage
929	                              defaultMessage="Ship to Address"
930	                              id="product_view.label.ship_to_address"
931	                            />
932	                          </Radio>
933	                          {storeLocatorEnabled && (
934	                            <Radio
935	                              value={DELIVERY_OPTIONS.PICKUP}
936	                              isDisabled={!pickupEnabled || (storeName && inventoryId && isSelectedStoreOutOfStock)}
937	                            >
938	                              <FormattedMessage
939	                                defaultMessage="Pick Up in Store"
940	                                id="product_view.label.pickup_in_store"
941	                              />
942	                            </Radio>
943	                          )}
944	                        </Stack>
945	                      </RadioGroup>
946	                    </Box>
947	
948	                    {storeLocatorEnabled && (
949	                      <>
950	                        {storeName && inventoryId && (
951	                          <Text color="black" fontWeight={600} mb={2} data-testid="store-stock-status-msg">
952	                            {!isSelectedStoreOutOfStock
953	                              ? intl.formatMessage(
954	                                  {
955	                                    id: 'product_view.status.in_stock_at_store',
956	                                    defaultMessage: 'In stock at {storeName}',
957	                                  },
958	                                  {
959	                                    storeName: (
960	                                      <Link
961	                                        as="button"
962	                                        color="blue.600"
963	                                        textDecoration="underline"
964	                                        onClick={onOpenStoreLocator}
965	                                      >
966	                                        {storeName}
967	                                      </Link>
968	                                    ),
969	                                  },
970	                                )
971	                              : intl.formatMessage(
972	                                  {
973	                                    id: 'product_view.status.out_of_stock_at_store',
974	                                    defaultMessage: 'Out of Stock at {storeName}',
975	                                  },
976	                                  {
977	                                    storeName: (
978	                                      <Link
979	                                        as="button"
980	                                        color="blue.600"
981	                                        textDecoration="underline"
982	                                        onClick={onOpenStoreLocator}
983	                                      >
984	                                        {storeName}
985	                                      </Link>
986	                                    ),
987	                                  },
988	                                )}
989	                          </Text>
990	                        )}
991	
992	                        {/* Show label if pickup is disabled due to no store/inventoryId */}
993	                        {!pickupEnabled && !storeName && !inventoryId && (
994	                          <Text color="black" fontWeight={600} mb={3} data-testid="pickup-select-store-msg">
995	                            <FormattedMessage
996	                              defaultMessage="Pick up in "
997	                              id="product_view.label.pickup_in_select_store_prefix"
998	                            />{' '}
999	                            <Link as="button" color="blue.600" textDecoration="underline" onClick={onOpenStoreLocator}>
1000	                              <FormattedMessage
1001	                                defaultMessage="Select Store"
1002	                                id="product_view.label.select_store_link"
1003	                              />
1004	                            </Link>
1005	                          </Text>
1006	                        )}
1007	                      </>
1008	                    )}
1009	                  </>
1010	                )}
1011	                <Box display={isProductPartOfSet ? 'block' : ['none', 'none', 'none', 'block']}>
1012	                  {renderActionButtons()}
1013	                </Box>
1014	              </Box>
1015	            </Box>
1016	          </VStack>
1017	        </Flex>
1018	
1019	        {/* Sticky call-to-action buttons for mobile and certain product types */}
1020	        <Box
1021	          position="fixed"
1022	          bg="white"
1023	          width="100%"
1024	          display={isProductPartOfSet || isProductPartOfBundle ? 'none' : ['block', 'block', 'block', 'none']}
1025	          p={[4, 4, 6]}
1026	          left={0}
1027	          bottom={0}
1028	          zIndex={2}
1029	          boxShadow={theme.shadows.top}
1030	        >
1031	          {renderActionButtons()}
1032	        </Box>
1033	
1034	        {/* Loading overlay during express payment confirmation */}
1035	        {confirmingBasket && <LoadingSpinner wrapperStyles={{ height: '100vh' }} />}
1036	      </Flex>
1037	    );
1038	  },
1039	);
1040	
1041	ProductView.displayName = 'ProductView';
1042	
1043	/*
1044	 * The base file's `ProductViewHeader.propTypes` / `ProductView.propTypes` blocks are not
1045	 * carried over: the `ProductViewHeaderProps` / `ProductViewProps` types above express the
1046	 * same prop contract, and do so at compile time for every caller rather than as a dev-only
1047	 * runtime warning. Keeping both would duplicate the contract in two places that can drift.
1048	 */
1049	
1050	export default ProductView;
